STORIES.splice(0,STORIES.length,...[{"id": "a1-cafe-manana", "level": "A1", "title": "قهوة الصبح", "desc": "لونا بتطلب قهوة وفطار في كافيه صغير قبل الشغل.", "lines": [{"speaker": "paco", "es": "Buenos días, ¿qué va a tomar?", "ar": "صباح الخير، هتاخدي إيه؟"}, {"speaker": "luna", "es": "Buenos días. Un café con leche, por favor.", "ar": "صباح الخير. قهوة بلبن لو سمحت."}, {"speaker": "paco", "es": "¿Algo más? Tenemos cruasanes.", "ar": "حاجة تانية؟ عندنا كرواسون."}, {"speaker": "luna", "es": "Sí, un cruasán también.", "ar": "أيوه، كرواسون كمان."}, {"speaker": "paco", "es": "¿Para aquí o para llevar?", "ar": "هنا ولا تيك أواي؟"}, {"speaker": "luna", "es": "Para llevar, gracias.", "ar": "تيك أواي، شكرًا."}, {"speaker": "paco", "es": "Son tres euros con cincuenta.", "ar": "تلاتة يورو ونص."}, {"speaker": "luna", "es": "Aquí tiene. ¡Que tenga buen día!", "ar": "اتفضل. نهارك سعيد!"}], "questions": [{"q": "لونا طلبت إيه؟", "options": ["قهوة بلبن وكرواسون", "عصير برتقال بس", "شاي وكيك"], "answer": "قهوة بلبن وكرواسون", "rationale": "قالت «Un café con leche» و«un cruasán también» يعني قهوة بلبن وكرواسون. مفيش شاي ولا عصير في الكلام."}, {"q": "لونا هتاخد الطلب فين؟", "options": ["في الشغل", "تيك أواي", "هنا في الكافيه"], "answer": "تيك أواي", "rationale": "قالت «Para llevar» يعني تيك أواي. «Para aquí» كانت هتعني هنا، والشغل ما اتذكرش."}, {"q": "الحساب كام؟", "options": ["خمسة يورو", "تلاتاشر يورو", "تلاتة يورو ونص"], "answer": "تلاتة يورو ونص", "rationale": "«tres euros con cincuenta» يعني تلاتة يورو ونص. خمسة وتلاتاشر أرقام ما اتقالتش."}, {"q": "مين بياخد الطلب؟", "options": ["باكو", "عميل تاني", "لونا"], "answer": "باكو", "rationale": "باكو هو اللي سأل «¿qué va a tomar?» وقال الحساب، يبقى هو اللي بياخد الطلب. لونا هي العميلة."}]}, {"id": "a1-camino-metro", "level": "A1", "title": "الطريق للمترو", "desc": "لونا بتسأل في الشارع عن محطة المترو.", "lines": [{"speaker": "luna", "es": "Perdone, ¿dónde está el metro?", "ar": "لو سمحت، فين المترو؟"}, {"speaker": "paco", "es": "¿El metro? Siga todo recto.", "ar": "المترو؟ امشي على طول."}, {"speaker": "luna", "es": "¿Todo recto?", "ar": "على طول؟"}, {"speaker": "paco", "es": "Sí, y luego gire a la izquierda.", "ar": "أيوه، وبعدين خد شمال."}, {"speaker": "luna", "es": "¿Está lejos?", "ar": "بعيد؟"}, {"speaker": "paco", "es": "No, está muy cerca. Dos minutos.", "ar": "لأ، قريب أوي. دقيقتين."}, {"speaker": "luna", "es": "Muchas gracias.", "ar": "شكرًا جدًا."}, {"speaker": "paco", "es": "De nada. Adiós.", "ar": "العفو. مع السلامة."}], "questions": [{"q": "لونا بتدور على إيه؟", "options": ["التاكسي", "الأتوبيس", "المترو"], "answer": "المترو", "rationale": "سألت «¿dónde está el metro?» يعني بتدور على المترو. أتوبيس وتاكسي ما اتذكروش."}, {"q": "لونا تمشي إزاي الأول؟", "options": ["على اليمين", "على طول", "على الشمال"], "answer": "على طول", "rationale": "«Todo recto» يعني على طول. اليمين ما اتقالش، والشمال بيجي بعدين."}, {"q": "وبعد كده تروح فين؟", "options": ["على طول تاني", "على اليمين", "على الشمال"], "answer": "على الشمال", "rationale": "«gire a la izquierda» يعني خد شمال. اليمين غلط لأن izquierda = شمال."}, {"q": "المترو قريب ولا بعيد؟", "options": ["بعيد، عشرين دقيقة", "قريب، دقيقتين", "قريب، عشر دقايق"], "answer": "قريب، دقيقتين", "rationale": "قال «está muy cerca. Dos minutos» يعني قريب أوي، دقيقتين. الأرقام التانية ما اتقالتش."}]}, {"id": "a1-mercado-fruta", "level": "A1", "title": "في السوق", "desc": "لونا بتشتري فاكهة من السوق وبتسأل عن الأسعار.", "lines": [{"speaker": "luna", "es": "Hola, ¿a cuánto están los plátanos?", "ar": "أهلًا، الموز بكام؟"}, {"speaker": "paco", "es": "A dos euros el kilo.", "ar": "بتنين يورو الكيلو."}, {"speaker": "luna", "es": "Vale. ¿Y las manzanas?", "ar": "ماشي. والتفاح؟"}, {"speaker": "paco", "es": "Las manzanas, a uno ochenta.", "ar": "التفاح بيورو وتمانين."}, {"speaker": "luna", "es": "Quiero un kilo de plátanos, por favor.", "ar": "عايزة كيلو موز لو سمحت."}, {"speaker": "paco", "es": "¿Algo más?", "ar": "حاجة تانية؟"}, {"speaker": "luna", "es": "No, nada más. ¿Cuánto es?", "ar": "لأ، بس كده. كام الحساب؟"}, {"speaker": "paco", "es": "Dos euros.", "ar": "تنين يورو."}, {"speaker": "luna", "es": "Tome. Gracias, adiós.", "ar": "اتفضل. شكرًا، مع السلامة."}], "questions": [{"q": "الموز بكام الكيلو؟", "options": ["تنين يورو", "يورو وتمانين", "تلاتة يورو"], "answer": "تنين يورو", "rationale": "«A dos euros el kilo» يعني بتنين يورو الكيلو. اليورو وتمانين ده سعر التفاح مش الموز."}, {"q": "التفاح بكام؟", "options": ["تنين يورو", "يورو وتمانين", "يورو بس"], "answer": "يورو وتمانين", "rationale": "«a uno ochenta» يعني يورو وتمانين سنت. التنين يورو سعر الموز."}, {"q": "لونا اشترت إيه في الآخر؟", "options": ["كيلو موز بس", "كيلو تفاح", "كيلو موز وكيلو تفاح"], "answer": "كيلو موز بس", "rationale": "قالت «un kilo de plátanos» وسألت عن التفاح بس من غير ما تشتري، وردت على «¿Algo más?» بـ «No, nada más» يعني بس كده."}, {"q": "دفعت كام؟", "options": ["يورو وتمانين", "تلاتة يورو وتمانين", "تنين يورو"], "answer": "تنين يورو", "rationale": "كيلو موز بتنين يورو، والبائع قال «Dos euros». التلاتة وتمانين غلط لأنها ماشترتش تفاح."}]}, {"id": "a1-vecino-nuevo", "level": "A1", "title": "جار جديد", "desc": "لونا بتعرّف نفسها على جارها الجديد في الأسانسير.", "lines": [{"speaker": "luna", "es": "¡Hola! ¿Eres nuevo en el edificio?", "ar": "أهلًا! إنت جديد في العمارة؟"}, {"speaker": "paco", "es": "Sí, me llamo Paco. Vivo en el tercero.", "ar": "أيوه، أنا اسمي باكو. ساكن في الدور التالت."}, {"speaker": "luna", "es": "Encantada, Paco. Yo soy Luna, del segundo.", "ar": "تشرفنا يا باكو. أنا لونا، من الدور التاني."}, {"speaker": "paco", "es": "Encantado, Luna. ¿Llevas mucho tiempo aquí?", "ar": "تشرفنا يا لونا. إنتي ساكنة هنا من زمان؟"}, {"speaker": "luna", "es": "Sí, dos años.", "ar": "أيوه، بقالي سنتين."}, {"speaker": "paco", "es": "¿Y trabajas cerca?", "ar": "وبتشتغلي قريب من هنا؟"}, {"speaker": "luna", "es": "Sí, trabajo en una farmacia, al lado del metro.", "ar": "أيوه، بشتغل في صيدلية جنب المترو."}, {"speaker": "paco", "es": "¡Qué bien! Hasta luego, Luna.", "ar": "جميل! أشوفك بعدين يا لونا."}, {"speaker": "luna", "es": "Hasta luego. ¡Bienvenido!", "ar": "أشوفك بعدين. أهلًا بيك!"}], "questions": [{"q": "باكو ساكن في الدور الكام؟", "options": ["الرابع", "التاني", "التالت"], "answer": "التالت", "rationale": "قال «Vivo en el tercero» يعني ساكن في الدور التالت. التاني ده دور لونا."}, {"q": "لونا ساكنة هنا من قد إيه؟", "options": ["تلات سنين", "سنتين", "سنة"], "answer": "سنتين", "rationale": "قالت «dos años» يعني بقالها سنتين ساكنة هنا. سنة وتلاتة ما اتقالوش."}, {"q": "لونا بتشتغل فين؟", "options": ["في صيدلية جنب المترو", "في سوبرماركت", "في كافيه"], "answer": "في صيدلية جنب المترو", "rationale": "قالت «trabajo en una farmacia, al lado del metro» يعني بتشتغل في صيدلية جنب المترو. الكافيه والسوبرماركت ما اتذكروش."}, {"q": "لونا رحّبت بباكو إزاي في الآخر؟", "options": ["«¡Buenas tardes!»", "«¡Hasta mañana!»", "«¡Bienvenido!»"], "answer": "«¡Bienvenido!»", "rationale": "قالت «¡Bienvenido!» يعني أهلًا بيك. مساء الخير وأشوفك بكرة ما اتقالوش."}]}, {"id": "a2-paquete-otra-sucursal", "level": "A2", "title": "الطرد في الفرع التاني", "desc": "لونا بتروح تستلم طردها وتكتشف إنه وصل لفرع تاني من نفس المحل.", "lines": [{"speaker": "luna", "es": "Buenos días. Vengo a recoger un paquete.", "ar": "صباح الخير. جاية أستلم طرد."}, {"speaker": "paco", "es": "Buenos días. ¿Tiene el código de seguimiento?", "ar": "صباح الخير. مع حضرتك رقم التتبع؟"}, {"speaker": "luna", "es": "Sí, mire. Me llegó un mensaje ayer.", "ar": "أيوه، اتفضل. وصلتني رسالة إمبارح."}, {"speaker": "paco", "es": "Gracias... Mmm, qué raro. Este paquete no está aquí.", "ar": "شكرًا... همم، غريب. الطرد ده مش هنا."}, {"speaker": "luna", "es": "¿Cómo que no está? El mensaje dice que es esta tienda.", "ar": "إزاي مش هنا؟ الرسالة مكتوب فيها المحل ده."}, {"speaker": "paco", "es": "Ya lo veo, pero mire la dirección: es la otra sucursal, la de la calle Mayor.", "ar": "شايف، بس لو سمحتي بصّي على العنوان: ده الفرع التاني، اللي في شارع مايور."}, {"speaker": "luna", "es": "¡Ay, es verdad! No leí bien el mensaje.", "ar": "آه، صحيح! أنا مقريتش الرسالة كويس."}, {"speaker": "paco", "es": "No pasa nada, le pasa a mucha gente. Las dos sucursales tienen el mismo nombre, por eso pasa.", "ar": "ولا يهمك، بيحصل مع ناس كتير. الفرعين ليهم نفس الاسم، عشان كده بيحصل."}, {"speaker": "luna", "es": "¿Y puedo recogerlo allí hoy?", "ar": "وأقدر أستلمه من هناك النهارده؟"}, {"speaker": "paco", "es": "Sí, claro. Cierran a las nueve. Voy a llamar a la otra sucursal para avisar.", "ar": "أيوه طبعًا. بيقفلوا الساعة تسعة. هكلم الفرع التاني عشان أبلغهم."}, {"speaker": "luna", "es": "Muy amable. ¿Sabe si hay un metro cerca?", "ar": "حضرتك ذوق أوي. تعرف فيه مترو قريب؟"}, {"speaker": "paco", "es": "Sí, la estación de Ópera está a cinco minutos a pie.", "ar": "أيوه، محطة أوبرا على بعد خمس دقايق مشي."}, {"speaker": "luna", "es": "Perfecto. Entonces paso por allí después del trabajo.", "ar": "تمام. يبقى هعدّى عليه بعد الشغل."}, {"speaker": "paco", "es": "De acuerdo. ¡Que tenga buen día!", "ar": "ماشي. نهارك سعيد!"}, {"speaker": "luna", "es": "Gracias, igualmente.", "ar": "شكرًا، وحضرتك كمان."}], "questions": [{"q": "لونا راحت المحل ليه؟", "options": ["تشتري هدية", "تستلم طرد", "تقدّم شكوى"], "answer": "تستلم طرد", "rationale": "أول جملة قالتها «Vengo a recoger un paquete» يعني جاية أستلم طرد. مفيش هدية ولا شكوى في الكلام."}, {"q": "ليه الطرد مش موجود في المحل ده؟", "options": ["وصل لفرع تاني ليه نفس اسم المحل", "لسه في الطريق", "اترجع للمرسل"], "answer": "وصل لفرع تاني ليه نفس اسم المحل", "rationale": "الموظف لقى إن العنوان في الرسالة بتاع الفرع التاني، وقال «Las dos sucursales tienen el mismo nombre». مفيش كلام عن تأخير ولا إرجاع."}, {"q": "إيه سبب اللخبطة؟", "options": ["الموظف ضيّع الطرد", "شركة الشحن غلطت", "لونا مقريتش العنوان كويس"], "answer": "لونا مقريتش العنوان كويس", "rationale": "لونا نفسها قالت «No leí bien el mensaje» يعني هي اللي مقريتش الرسالة كويس. ما حدش قال إن الموظف ضيّع الطرد أو إن الشحن غلط."}, {"q": "الموظف عمل إيه عشان يساعد لونا؟", "options": ["هيبعت الطرد لبيتها", "هيكلم الفرع التاني يبلغهم", "قالها تعالى بكرة"], "answer": "هيكلم الفرع التاني يبلغهم", "rationale": "قال «Voy a llamar a la otra sucursal para avisar» يعني هيكلم الفرع التاني عشان يبلغهم. مفيش توصيل للبيت في الكلام."}, {"q": "لونا هتستلم الطرد إمتى وفين؟", "options": ["النهارده من الفرع التاني بعد الشغل", "بكرة من نفس المحل", "لما يوصل هنا بعد يومين"], "answer": "النهارده من الفرع التاني بعد الشغل", "rationale": "قالت «paso por allí después del trabajo» يعني هتعدّى عليه بعد الشغل، و«allí» بتشاور على الفرع التاني."}, {"q": "الفرع التاني بيقفل الساعة كام؟", "options": ["الساعة خمسة", "الساعة اتناشر", "الساعة تسعة"], "answer": "الساعة تسعة", "rationale": "قال «Cierran a las nueve» يعني بيقفلوا الساعة تسعة. خمسة واتناشر ما اتقالوش."}]}, {"id": "a2-cita-doctor", "level": "A2", "title": "موعد الدكتور", "desc": "لونا بتتصل بالعيادة عشان تغيّر ميعاد كشفها.", "lines": [{"speaker": "paco", "es": "Clínica Sol, buenos días.", "ar": "عيادة سول، صباح الخير."}, {"speaker": "luna", "es": "Buenos días. Tengo una cita mañana y quiero cambiarla.", "ar": "صباح الخير. عندي ميعاد بكرة وعايزة أغيّره."}, {"speaker": "paco", "es": "Muy bien. ¿A qué hora es su cita?", "ar": "ماشي. ميعاد حضرتك الساعة كام؟"}, {"speaker": "luna", "es": "A las diez, con la doctora Ruiz.", "ar": "الساعة عشرة، مع الدكتورة رويث."}, {"speaker": "paco", "es": "Sí, aquí está. ¿Qué día le viene bien?", "ar": "أيوه، لقيته. أنهي يوم يناسب حضرتك؟"}, {"speaker": "luna", "es": "¿Es posible el jueves por la tarde?", "ar": "ممكن الخميس بعد الضهر؟"}, {"speaker": "paco", "es": "El jueves... hay un hueco libre a las cinco y media.", "ar": "الخميس... فيه ميعاد فاضي الساعة خمسة ونص."}, {"speaker": "luna", "es": "Perfecto, me viene muy bien.", "ar": "تمام، ده يناسبني أوي."}, {"speaker": "paco", "es": "Entonces, el jueves a las cinco y media con la doctora Ruiz.", "ar": "يبقى الخميس الساعة خمسة ونص مع الدكتورة رويث."}, {"speaker": "luna", "es": "Muy bien. ¿Tengo que traer algo?", "ar": "ماشي. لازم أجيب حاجة معايا؟"}, {"speaker": "paco", "es": "Solo su tarjeta sanitaria.", "ar": "بس كارت التأمين الصحي بتاع حضرتك."}, {"speaker": "luna", "es": "De acuerdo. Muchas gracias.", "ar": "ماشي. شكرًا جدًا."}, {"speaker": "paco", "es": "A usted. Hasta el jueves.", "ar": "العفو. نشوف حضرتك الخميس."}], "questions": [{"q": "لونا بتتصل بالعيادة ليه؟", "options": ["تلغي الميعاد نهائي", "تغيّر ميعادها", "تحجز ميعاد جديد"], "answer": "تغيّر ميعادها", "rationale": "قالت «quiero cambiarla» يعني عايزة أغيّر الميعاد، مش تلغيه. والميعاد أصلًا موجود، فمش حجز جديد."}, {"q": "ميعادها الأصلي كان إمتى؟", "options": ["الخميس الساعة خمسة", "بكرة الساعة خمسة ونص", "بكرة الساعة عشرة"], "answer": "بكرة الساعة عشرة", "rationale": "قالت «Tengo una cita mañana» و«A las diez» يعني بكرة الساعة عشرة. خمسة ونص ده الميعاد الجديد."}, {"q": "الميعاد الجديد بقى إمتى؟", "options": ["الخميس الساعة خمسة ونص", "الجمعة الساعة خمسة", "الخميس الساعة عشرة"], "answer": "الخميس الساعة خمسة ونص", "rationale": "الموظف قال «el jueves... a las cinco y media» ولونا وافقت. الجمعة ما اتذكرتش خالص."}, {"q": "لازم تجيب إيه معاها؟", "options": ["فلوس الكشف كاش", "كارت التأمين الصحي", "تحاليل قديمة"], "answer": "كارت التأمين الصحي", "rationale": "قال «Solo su tarjeta sanitaria» يعني بس كارت التأمين الصحي. مفيش كلام عن فلوس ولا تحاليل."}, {"q": "الدكتورة اللي بتكشف على لونا اسمها إيه؟", "options": ["سول", "لونا", "رويث"], "answer": "رويث", "rationale": "«con la doctora Ruiz» يعني مع الدكتورة رويث. سول ده اسم العيادة، ولونا هي المريضة."}]}, {"id": "a2-farmacia-resfriado", "level": "A2", "title": "عند الصيدلي", "desc": "باكو عيان وبيشرح للصيدلانية أعراض البرد اللي عنده.", "lines": [{"speaker": "luna", "es": "Buenas tardes, ¿qué necesita?", "ar": "مساء الخير، محتاج إيه؟"}, {"speaker": "paco", "es": "Buenas. Estoy resfriado desde ayer.", "ar": "مساء الخير. أنا واخد برد من إمبارح."}, {"speaker": "luna", "es": "¿Qué síntomas tiene?", "ar": "عندك أعراض إيه؟"}, {"speaker": "paco", "es": "Me duele la garganta y tengo tos.", "ar": "حلقي بيوجعني وعندي كحة."}, {"speaker": "luna", "es": "¿Tiene fiebre?", "ar": "عندك سخونة؟"}, {"speaker": "paco", "es": "No, fiebre no tengo.", "ar": "لأ، مفيش سخونة."}, {"speaker": "luna", "es": "Vale. Le doy un jarabe para la tos y pastillas para la garganta.", "ar": "ماشي. هديك شراب للكحة وأقراص للحلق."}, {"speaker": "paco", "es": "¿Cómo se toman?", "ar": "باخدهم إزاي؟"}, {"speaker": "luna", "es": "El jarabe y las pastillas, como pone en el prospecto. Cualquier duda, me pregunta.", "ar": "الشراب والأقراص، زي ما مكتوب في النشرة اللي في العلبة. أي سؤال، اسألني."}, {"speaker": "paco", "es": "¿Y cuándo me voy a encontrar mejor?", "ar": "وحأتحسن إمتى؟"}, {"speaker": "luna", "es": "Depende. Si los síntomas empeoran o no mejora, vaya al médico.", "ar": "ده بيختلف. لو الأعراض زادت أو مفيش تحسن، روح للدكتور."}, {"speaker": "paco", "es": "Muy bien. ¿Cuánto es todo?", "ar": "ماشي. كام الحساب كله؟"}, {"speaker": "luna", "es": "Doce euros con sesenta.", "ar": "اتناشر يورو وستين."}, {"speaker": "paco", "es": "Aquí tiene. Gracias.", "ar": "اتفضلي. شكرًا."}], "questions": [{"q": "باكو ماله؟", "options": ["واخد برد من إمبارح", "معدته واجعاه من أكل إمبارح بالليل", "ظهره بيوجعه من الشغل والوقفة الكتير"], "answer": "واخد برد من إمبارح", "rationale": "قال «Estoy resfriado desde ayer» يعني واخد برد من إمبارح. مفيش معدة ولا ضهر في الكلام."}, {"q": "أعراضه إيه؟", "options": ["كحة جافة وسخونة عالية من الصبح", "وجع في الحلق وكحة", "سخونة وصداع شديد من يومين"], "answer": "وجع في الحلق وكحة", "rationale": "قال «Me duele la garganta y tengo tos» ونفى السخونة: «fiebre no tengo». فأي اختيار فيه سخونة غلط."}, {"q": "الصيدلانية ادته إيه؟", "options": ["قطرة للعين ومرهم لوجع الظهر", "مضاد حيوي وخافض للحرارة والصداع", "شراب للكحة وأقراص للحلق"], "answer": "شراب للكحة وأقراص للحلق", "rationale": "قالت «un jarabe para la tos y pastillas para la garganta». مضاد حيوي وقطرة ما اتذكروش."}, {"q": "الصيدلانية قالت لباكو ياخد الدوا إزاي؟", "options": ["زي اللي مكتوب في النشرة اللي جوه العلبة", "من دماغه ومن غير ما يسأل الصيدلانية خالص", "زي ما صاحبه قاله إمبارح ومن غير ما يسأل حد"], "answer": "زي اللي مكتوب في النشرة اللي جوه العلبة", "rationale": "قالت «como pone en el prospecto» يعني زي ما مكتوب في النشرة، ولو عنده سؤال يسألها. مفيش مواعيد محددة في الكلام."}, {"q": "الصيدلانية قالتله يروح للدكتور إمتى؟", "options": ["بعد ما يخلص الدوا كله مهما كان حاسس", "لو الأعراض زادت أو مفيش تحسن", "لو عايز يشتري دوا تاني من نفس النوع"], "answer": "لو الأعراض زادت أو مفيش تحسن", "rationale": "قالت «Si los síntomas empeoran o no mejora, vaya al médico» يعني لو الأعراض زادت أو مفيش تحسن يروح للدكتور. محدش حدد موعد معين."}, {"q": "دفع كام في الآخر؟", "options": ["اتنين يورو وستين", "عشرين يورو وخمسة وسبعين سنت", "اتناشر يورو وستين"], "answer": "اتناشر يورو وستين", "rationale": "«Doce euros con sesenta» يعني اتناشر يورو وستين سنت. doce = اتناشر، مش اتنين."}]}, {"id": "a2-tren-perdido", "level": "A2", "title": "القطار فات", "desc": "باكو وصل المحطة متأخر ولقى القطار ماشي، وبيدور على حل.", "lines": [{"speaker": "paco", "es": "¡Qué mala suerte! He perdido el tren de las nueve.", "ar": "حظي وحش أوي! قطر التسعة فاتني."}, {"speaker": "luna", "es": "¿A qué hora ha llegado usted?", "ar": "حضرتك وصلت الساعة كام؟"}, {"speaker": "paco", "es": "A las nueve y cinco. El autobús llegó tarde.", "ar": "الساعة تسعة وخمسة. الأتوبيس اتأخر."}, {"speaker": "luna", "es": "Entiendo. ¿Adónde viaja?", "ar": "فاهمة. مسافر فين؟"}, {"speaker": "paco", "es": "A Valencia. Tengo una reunión a las doce.", "ar": "فالنسيا. عندي اجتماع الساعة اتناشر."}, {"speaker": "luna", "es": "Hay otro tren a las nueve y media. Llega a las once y veinte.", "ar": "فيه قطار تاني الساعة تسعة ونص. بيوصل الساعة إحداشر وعشرين."}, {"speaker": "paco", "es": "¿Y llego a tiempo para la reunión?", "ar": "وهلحق الاجتماع؟"}, {"speaker": "luna", "es": "Sí, si sale de la estación rápido. Hay taxis en la puerta.", "ar": "أيوه، لو خرجت من المحطة بسرعة. فيه تاكسيات على الباب."}, {"speaker": "paco", "es": "Vale, quiero un billete para ese tren.", "ar": "ماشي، عايز تذكرة للقطار ده."}, {"speaker": "luna", "es": "¿Su billete anterior era flexible?", "ar": "تذكرتك القديمة كانت قابلة للتعديل؟"}, {"speaker": "paco", "es": "Sí, era flexible.", "ar": "أيوه، كانت قابلة للتعديل."}, {"speaker": "luna", "es": "Entonces el cambio es gratis. Aquí tiene su nuevo billete.", "ar": "يبقى التغيير ببلاش. اتفضل تذكرتك الجديدة."}, {"speaker": "paco", "es": "¡Muchas gracias! Me ha salvado.", "ar": "شكرًا جدًا! حضرتك أنقذتيني بجد!"}], "questions": [{"q": "ليه باكو فاته القطار؟", "options": ["الأتوبيس اللي جايبه اتأخر", "راح محطة تانية خالص في طرف المدينة التاني", "نام وصاحي متأخر من كتر السهر ليلتها"], "answer": "الأتوبيس اللي جايبه اتأخر", "rationale": "قال «El autobús llegó tarde» يعني الأتوبيس اتأخر، وده سبب إنه وصل تسعة وخمسة. مفيش كلام عن نوم ولا محطة غلط."}, {"q": "باكو مسافر فين وليه؟", "options": ["فالنسيا أجازة", "مدريد عشان فرح", "فالنسيا عشان اجتماع"], "answer": "فالنسيا عشان اجتماع", "rationale": "قال «A Valencia. Tengo una reunión a las doce» يعني رايح فالنسيا لاجتماع الساعة اتناشر، مش أجازة."}, {"q": "القطار التاني بيمشي إمتى ويوصل إمتى؟", "options": ["يمشي تسعة ونص ويوصل إحداشر وعشرين", "يمشي تسعة ويوصل إحداشر", "يمشي عشرة ويوصل اتناشر"], "answer": "يمشي تسعة ونص ويوصل إحداشر وعشرين", "rationale": "«a las nueve y media... Llega a las once y veinte» يعني يمشي تسعة ونص ويوصل إحداشر وعشرين، فهو هيوصل قبل اجتماع اتناشر."}, {"q": "ليه التغيير طلع ببلاش؟", "options": ["عرض خاص من الشركة للعملاء المميزين بس", "تذكرته كانت قابلة للتعديل", "القطار نفسه اتأخر عن معاده بكتير"], "answer": "تذكرته كانت قابلة للتعديل", "rationale": "الموظفة سألت «¿era flexible?» ولما قال أيوه قالت «el cambio es gratis». مفيش عرض خاص في الكلام."}, {"q": "الموظفة نصحته يعمل إيه عشان يلحق الاجتماع؟", "options": ["يأجل الاجتماع", "يركب أتوبيس تاني", "يخرج من المحطة بسرعة وياخد تاكسي"], "answer": "يخرج من المحطة بسرعة وياخد تاكسي", "rationale": "قالت «si sale de la estación rápido» و«Hay taxis en la puerta». هي ما قالتش يأجل الاجتماع."}]}, {"id": "b1-piso-alquiler", "level": "B1", "title": "نسكن في الشقة ولا لأ؟", "desc": "لونا وباكو شافوا شقة للإيجار وبيحبوا يقرروا، كل واحد شايف حاجة مختلفة.", "lines": [{"speaker": "luna", "es": "Bueno, ¿qué te ha parecido el piso?", "ar": "طيب، الشقة عجبتك؟"}, {"speaker": "paco", "es": "A mí me ha encantado. Es grande y tiene mucha luz.", "ar": "أنا عجبتني جدًا. واسعة وفيها نور كتير."}, {"speaker": "luna", "es": "Sí, es verdad, pero está un poco lejos del centro.", "ar": "أيوه صحيح، بس بعيدة شوية عن وسط البلد."}, {"speaker": "paco", "es": "Ya, pero por eso es más barata. Con lo que ahorramos podemos pagar el transporte.", "ar": "أيوه، بس عشان كده هي أرخص. اللي هنوفره يكفي مواصلاتنا."}, {"speaker": "luna", "es": "No sé... yo tardaría cuarenta minutos en llegar al trabajo.", "ar": "مش متأكدة... أنا هاخد أربعين دقيقة عشان أوصل الشغل."}, {"speaker": "paco", "es": "¿Y si nos mudamos y lo probamos unos meses? El contrato es de once meses.", "ar": "طيب ما نسكن ونجرب كام شهر؟ العقد أصلاً إحداشر شهر."}, {"speaker": "luna", "es": "Es que también me preocupa la cocina. Es muy pequeña.", "ar": "المشكلة إني قلقانة من المطبخ كمان. صغير أوي."}, {"speaker": "paco", "es": "Hombre, pero tú casi no cocinas entre semana.", "ar": "يا ستي، بس إنتي أصلاً مش بتطبخي وسط الأسبوع."}, {"speaker": "luna", "es": "¡Eso no es verdad! Cocino casi todos los días.", "ar": "ده مش صح! أنا بطبخ كل يوم تقريبًا."}, {"speaker": "paco", "es": "Vale, vale, tienes razón. Entonces, ¿qué hacemos?", "ar": "ماشي ماشي، معاكي حق. طيب نعمل إيه؟"}, {"speaker": "luna", "es": "Mira, me gusta el piso, pero quiero ver otro que hay cerca del metro. Si no nos convence, nos quedamos con este.", "ar": "بص، الشقة عجبتني، بس عايزة أشوف شقة تانية جنب المترو. لو معجبتناش، ناخد دي."}, {"speaker": "paco", "es": "Me parece justo. Pero hay que decidir rápido, que el dueño dijo que tiene más interesados.", "ar": "كلامك منطقي. بس لازم نقرر بسرعة، صاحب الشقة قال إنه في ناس تانية مهتمة."}, {"speaker": "luna", "es": "Vale. Mañana vemos el otro y por la noche decidimos.", "ar": "ماشي. بكرة نشوف التانية وبالليل نقرر."}, {"speaker": "paco", "es": "Trato hecho.", "ar": "اتفقنا."}], "questions": [{"q": "باكو شايف الشقة إزاي؟", "options": ["صغيرة وغالية أوي فوق ميزانيتهم", "قريبة من شغلهم بعشر دقايق بس", "عجبته جدًا: واسعة ومنورة"], "answer": "عجبته جدًا: واسعة ومنورة", "rationale": "قال «me ha encantado. Es grande y tiene mucha luz». القرب من الشغل مش ميزتها، دي نقطة ضعفها عند لونا."}, {"q": "إيه مشكلتين لونا مع الشقة؟", "options": ["بعيدة عن وسط البلد والمطبخ صغير", "غالية والأسانسير بايظ", "النور قليل والشارع صوته عالي"], "answer": "بعيدة عن وسط البلد والمطبخ صغير", "rationale": "قالت «lejos del centro» و«la cocina... Es muy pequeña». السعر أصلاً أرخص، والنور كتير حسب كلام باكو."}, {"q": "إيه حجة باكو إن البعد مش مشكلة؟", "options": ["لونا هتشتغل من البيت", "اللي هيوفروه من الإيجار يكفي المواصلات", "هيشتري عربية"], "answer": "اللي هيوفروه من الإيجار يكفي المواصلات", "rationale": "قال «Con lo que ahorramos podemos pagar el transporte». عربية وشغل من البيت ما اتذكروش."}, {"q": "إيه الاتفاق اللي وصلوله في الآخر؟", "options": ["يشوفوا شقة تانية جنب المترو، ولو معجبتهمش ياخدوا دي", "يدوروا في منطقة تانية خالص بعيدة عن وسط البلد وأسعارها أرخص", "يوقعوا على الشقة دي فورًا من غير تفكير"], "answer": "يشوفوا شقة تانية جنب المترو، ولو معجبتهمش ياخدوا دي", "rationale": "لونا اقترحت «quiero ver otro que hay cerca del metro. Si no nos convence, nos quedamos con este» وباكو وافق: «Me parece justo»."}, {"q": "ليه لازم يقرروا بسرعة؟", "options": ["العقد هيبدأ الأسبوع الجاي", "في ناس تانية مهتمة بالشقة", "صاحب الشقة مسافر"], "answer": "في ناس تانية مهتمة بالشقة", "rationale": "باكو قال «el dueño dijo que tiene más interesados» يعني في مهتمين تانيين. سفر صاحب الشقة ما اتذكرش."}, {"q": "مدة العقد المكتوبة قد إيه؟", "options": ["سنة كاملة", "ست شهور", "إحداشر شهر"], "answer": "إحداشر شهر", "rationale": "باكو قال «El contrato es de once meses» يعني إحداشر شهر. سنة كاملة وست شهور ما اتقالوش."}]}, {"id": "b1-cumple-confundido", "level": "B1", "title": "حفلة مارتا السبت ولا الحد؟", "desc": "لونا فاكرة إن حفلة مارتا يوم الحد وباكو فاكرها يوم السبت، وبيحاولوا يفهموا إيه اللي حصل.", "lines": [{"speaker": "paco", "es": "Oye, Luna, ¿has comprado ya el regalo para el sábado?", "ar": "يا لونا، اشتريتي هدية لحفلة السبت؟"}, {"speaker": "luna", "es": "¿Para el sábado? La fiesta de Marta es el domingo.", "ar": "ليه السبت؟ حفلة مارتا يوم الحد."}, {"speaker": "paco", "es": "No, mujer, es el sábado. Me lo dijo ella misma.", "ar": "لأ يا ستي، يوم السبت. هي نفسها قالتلي."}, {"speaker": "luna", "es": "Pues a mí me mandó un mensaje que ponía: «el domingo a las ocho».", "ar": "طيب أنا وصلتني رسالة مكتوب فيها: «يوم الحد الساعة تمنية»."}, {"speaker": "paco", "es": "Qué raro... A ver, enséñame el mensaje.", "ar": "غريب... طيب وريني الرسالة."}, {"speaker": "luna", "es": "Mira. «El domingo a las ocho en mi casa».", "ar": "بص. «يوم الحد الساعة تمنية في بيتي»."}, {"speaker": "paco", "es": "¡Ah, ya entiendo! Marta cambió el día. El sábado era el plan original.", "ar": "آه، فهمت! مارتا غيّرت اليوم. السبت كانت الخطة الأصلية."}, {"speaker": "luna", "es": "¿Y por qué no te avisó a ti?", "ar": "وليه مابلغتكش إنت؟"}, {"speaker": "paco", "es": "Pues... porque yo estaba sin móvil toda la semana, ¿no te acuerdas?", "ar": "عشان... أنا كنت من غير موبايل طول الأسبوع، مش فاكرة؟"}, {"speaker": "luna", "es": "¡Es verdad! Se te rompió la pantalla.", "ar": "صحيح! الشاشة كانت اتكسرت."}, {"speaker": "paco", "es": "Eso es. Menos mal que me lo has dicho, porque yo iba a aparecer allí el sábado con el regalo.", "ar": "بالظبط. الحمد لله إنك قلتيلي، كنت هروح هناك يوم السبت بالهدية."}, {"speaker": "luna", "es": "Imagina la cara de Marta. «Paco, la fiesta es mañana».", "ar": "تخيّل وش مارتا. «يا باكو، الحفلة بكرة»."}, {"speaker": "paco", "es": "Ja, ja. Bueno, el sábado entonces salimos nosotros, ¿no? Ya que estamos libres.", "ar": "هاها. طيب يوم السبت نخرج إحنا بقى، ماشي؟ ما إحنا فاضيين أصلاً."}, {"speaker": "luna", "es": "¡Buena idea! Así no perdemos el plan.", "ar": "فكرة حلوة! كده الخطة مش هتضيع."}], "questions": [{"q": "اللخبطة كانت في إيه؟", "options": ["الاتنين نسيوا مكان الحفلة", "لونا نسيت تجيب هدية", "باكو فاكر الحفلة السبت ولونا فاكراها الحد"], "answer": "باكو فاكر الحفلة السبت ولونا فاكراها الحد", "rationale": "باكو قال «es el sábado» ولونا قالت «es el domingo». المكان والهدية مش هما سبب اللخبطة، اللخبطة في اليوم بس."}, {"q": "إيه الحقيقة؟", "options": ["مارتا غيّرت اليوم من السبت للحد", "باكو غلط في قراية الرسالة", "لونا نسيت ميعاد الحفلة"], "answer": "مارتا غيّرت اليوم من السبت للحد", "rationale": "باكو فهم: «Marta cambió el día. El sábado era el plan original». باكو ماكانش غلطان، هو بس ما كانش يعرف بالتغيير."}, {"q": "ليه باكو ما عرفش بالتغيير؟", "options": ["كان مسافر", "كان من غير موبايل طول الأسبوع", "مارتا نسيت تكلمه"], "answer": "كان من غير موبايل طول الأسبوع", "rationale": "قال «estaba sin móvil toda la semana» ولونا فكرته إن الشاشة اتكسرت. سفر ما اتذكرش."}, {"q": "رسالة مارتا للونا كانت بتقول إيه؟", "options": ["الحد الساعة تمنية في بيتها", "الحد الساعة عشرة في بيتها", "السبت الساعة تمنية في مطعم"], "answer": "الحد الساعة تمنية في بيتها", "rationale": "لونا قرأت: «El domingo a las ocho en mi casa». المطعم والساعة عشرة ما اتقالوش."}, {"q": "اللي هيحصل يوم السبت في الآخر؟", "options": ["باكو هيروح بيت مارتا بالهدية", "هيروحوا حفلة مارتا يوم السبت", "لونا وباكو هيخرجوا لوحدهم"], "answer": "لونا وباكو هيخرجوا لوحدهم", "rationale": "باكو اقترح «el sábado entonces salimos nosotros» لأنهم فاضيين، ولونا وافقت. حفلة مارتا يوم الحد."}]}, {"id": "b1-oferta-trabajo", "level": "B1", "title": "عرض الشغل الجديد", "desc": "لونا جالها عرض شغل جديد وبتستشير باكو: فلوس أحسن ولا راحة أحسن؟", "lines": [{"speaker": "luna", "es": "Paco, tengo que contarte algo. Me han ofrecido otro trabajo.", "ar": "يا باكو، لازم أقولك على حاجة. جالي عرض شغل تاني."}, {"speaker": "paco", "es": "¡Anda! ¿Dónde?", "ar": "بجد! فين؟"}, {"speaker": "luna", "es": "En una empresa grande, en las afueras. Pagan un veinte por ciento más.", "ar": "في شركة كبيرة في أطراف المدينة. بيدفعوا أكتر بنسبة عشرين في المية."}, {"speaker": "paco", "es": "¡Un veinte por ciento! Eso está muy bien.", "ar": "عشرين في المية! ده كويس أوي."}, {"speaker": "luna", "es": "Sí, pero tardaría una hora en llegar. Ahora tardo diez minutos andando.", "ar": "أيوه، بس هاخد ساعة في الطريق. دلوقتي باخد عشر دقايق مشي."}, {"speaker": "paco", "es": "Buf, eso son dos horas al día. ¿Y el ambiente? ¿Has hablado con alguien de allí?", "ar": "أوف، دي ساعتين في اليوم. طيب والجو هناك؟ كلمتي حد بيشتغل هناك؟"}, {"speaker": "luna", "es": "Sí, he hablado con una chica que trabaja allí. Dice que el ambiente es bueno, pero hay mucha presión.", "ar": "أيوه، كلمت بنت بتشتغل هناك. قالت إن الجو كويس بس فيه ضغط كتير."}, {"speaker": "paco", "es": "¿Y en tu trabajo actual estás a gusto?", "ar": "وفي شغلك الحالي مرتاحة؟"}, {"speaker": "luna", "es": "La verdad es que sí. Me llevo bien con todos y el horario es flexible.", "ar": "الحقيقة أيوه. علاقتي كويسة بالكل والمواعيد مرنة."}, {"speaker": "paco", "es": "Pues yo creo que tienes que pensar qué es más importante para ti ahora: el dinero o la tranquilidad.", "ar": "أنا شايف إنك لازم تفكري إيه الأهم ليكي دلوقتي: الفلوس ولا راحة البال."}, {"speaker": "luna", "es": "Es que necesito ahorrar. Quiero hacer un máster el año que viene.", "ar": "المشكلة إني محتاجة أوفر. عايزة أعمل ماجستير السنة الجاية."}, {"speaker": "paco", "es": "Ah, eso cambia las cosas. Si ahorras ese veinte por ciento durante un año, ¿te llega?", "ar": "آه، ده بيغير الموضوع. لو وفّرتي العشرين في المية دول سنة كاملة، هيكفوكي؟"}, {"speaker": "luna", "es": "Sí, me llega justo.", "ar": "أيوه، يا دوب هيكفوني."}, {"speaker": "paco", "es": "Entonces yo lo aceptaría. Aguanta un año, ahorra, y luego ya veremos.", "ar": "يبقى أنا كنت هقبل. اصبري سنة، ووفّري، وبعدين نشوف."}, {"speaker": "luna", "es": "Tienes razón. Mañana les respondo que sí.", "ar": "معاك حق. بكرة هرد عليهم وأقولهم موافقة."}], "questions": [{"q": "ميزة الشغل الجديد الأساسية إيه؟", "options": ["أقرب للبيت بكتير من شغلها الحالي", "مرتب أعلى بعشرين في المية", "مواعيد مرنة تقدر تختارها بنفسها"], "answer": "مرتب أعلى بعشرين في المية", "rationale": "قالت «Pagan un veinte por ciento más». المواعيد المرنة دي ميزة شغلها الحالي، والجديد أبعد عن البيت."}, {"q": "عيب الشغل الجديد إيه؟", "options": ["ساعة طريق في كل اتجاه وضغط شغل كتير", "المرتب أقل", "المديرين وحشين"], "answer": "ساعة طريق في كل اتجاه وضغط شغل كتير", "rationale": "قالت «tardaría una hora en llegar» ونقلت عن البنت «hay mucha presión». المرتب أعلى مش أقل."}, {"q": "ليه لونا محتاجة الفلوس الزيادة؟", "options": ["عايزة تشتري عربية عشان مشاويرها اليومية", "عايزة تسافر أوروبا في الصيف مع أصحابها", "عايزة تعمل ماجستير السنة الجاية"], "answer": "عايزة تعمل ماجستير السنة الجاية", "rationale": "قالت «Quiero hacer un máster el año que viene» وإنها محتاجة توفر. عربية وسفر ما اتذكروش."}, {"q": "نصيحة باكو كانت إيه؟", "options": ["اطلبي مرتب أعلى من شغلك الحالي", "اقبلي واصبري سنة لحد ما توفري", "ارفضي فورًا"], "answer": "اقبلي واصبري سنة لحد ما توفري", "rationale": "قال «yo lo aceptaría. Aguanta un año, ahorra, y luego ya veremos». مفاوضة الشغل الحالي ما اتعرضتش."}, {"q": "قرار لونا النهائي إيه؟", "options": ["هتقبل العرض", "لسه محتارة", "هترفض العرض"], "answer": "هتقبل العرض", "rationale": "قالت «Mañana les respondo que sí» يعني بكرة هرد بالموافقة."}, {"q": "إيه اللي غيّر رأي باكو خلال الكلام؟", "options": ["لما عرف إن الطريق ساعة في كل اتجاه", "لما عرف إن التوفير هيحقق هدف الماجستير", "لما عرف إن الشركة كبيرة وليها فروع كتير برة"], "answer": "لما عرف إن التوفير هيحقق هدف الماجستير", "rationale": "أول ما عرف بالماجستير قال «eso cambia las cosas» يعني ده بيغير الموضوع، وساعتها بدأ يميل للقبول."}]}, {"id": "b1-movil-roto", "level": "B1", "title": "الموبايل يتصلح ولا نشتري جديد؟", "desc": "باكو راح محل صيانة بموبايل شاشته مكسورة، والفنية بتقوله الخيارات.", "lines": [{"speaker": "paco", "es": "Buenas. Se me ha roto la pantalla del móvil. ¿Tiene arreglo?", "ar": "مساء الخير. شاشة موبايلي اتكسرت. ليها تصليح؟"}, {"speaker": "luna", "es": "A ver... Sí, se puede cambiar. ¿Qué modelo es?", "ar": "ورّيني... أيوه، ممكن تتغير. الموديل إيه؟"}, {"speaker": "paco", "es": "Es un modelo de hace cuatro años.", "ar": "موديل من أربع سنين."}, {"speaker": "luna", "es": "Mire, la pantalla cuesta ochenta euros, más veinte de mano de obra.", "ar": "بص، الشاشة بتمانين يورو، وعشرين يورو مصنعية."}, {"speaker": "paco", "es": "Cien euros... no sé si merece la pena. El móvil ya es viejo.", "ar": "مية يورو... مش عارف يستاهل ولا لأ. الموبايل خلاص قديم."}, {"speaker": "luna", "es": "Entiendo. Depende. ¿Le funciona bien todo lo demás?", "ar": "فاهمة. ده على حسب. باقي الموبايل شغال كويس؟"}, {"speaker": "paco", "es": "La batería dura poco, pero lo demás va bien.", "ar": "البطارية بتفصل بسرعة، بس الباقي شغال كويس."}, {"speaker": "luna", "es": "Pues otra cosa: la batería de este modelo ya no se encuentra fácil. Si se la cambiamos dentro de unos meses, será otro gasto.", "ar": "طيب حاجة تانية: بطارية الموديل ده بقى صعب تلاقيها. لو غيّرناها بعد كام شهر، دي مصاريف تانية."}, {"speaker": "paco", "es": "O sea, que si lo arreglo ahora, en unos meses igual tengo otro problema.", "ar": "يعني لو صلحته دلوقتي، بعد شهور ممكن تظهرلي مشكلة تانية."}, {"speaker": "luna", "es": "Exacto. Yo le diría que se comprara uno nuevo. Con cien euros más lo que ahorra, tiene un móvil mejor.", "ar": "بالظبط. أنا كنت هقولك اشتري واحد جديد. بالمية يورو دول وشوية توفير هتجيب موبايل أحسن."}, {"speaker": "paco", "es": "¿Y no me estará vendiendo la moto?", "ar": "ومش بتضحكي عليّا عشان أشتري؟"}, {"speaker": "luna", "es": "No, si aquí solo reparamos, no vendemos móviles. Se lo digo porque es lo que yo haría.", "ar": "لأ، إحنا هنا بنصلح بس، مش بنبيع موبايلات. بقولك كده عشان ده اللي كنت هعمله أنا."}, {"speaker": "paco", "es": "Vale, me ha convencido. Entonces no hace falta el arreglo.", "ar": "ماشي، أقنعتيني. يبقى مش محتاج التصليح."}, {"speaker": "luna", "es": "Un consejo: antes de tirar el viejo, pase las fotos al ordenador.", "ar": "نصيحة: قبل ما ترمي القديم، انقل الصور على الكمبيوتر."}, {"speaker": "paco", "es": "¡Buena idea! Gracias por la honestidad.", "ar": "فكرة حلوة! شكرًا على صراحتك."}], "questions": [{"q": "تصليح الشاشة هيكلف كام؟", "options": ["عشرين يورو المصنعية لوحدها", "تمانين يورو سعر الشاشة لوحدها", "مية يورو بالكامل"], "answer": "مية يورو بالكامل", "rationale": "الشاشة بتمانين والمصنعية بعشرين، يعني المجموع مية: «ochenta euros, más veinte de mano de obra». التمانين والعشرين أجزاء مش المجموع."}, {"q": "ليه الفنية شايفة إن التصليح مش أحسن قرار؟", "options": ["الشاشة الجديدة هتبقى أضعف من الأصلية", "بطارية الموديل ده بقت صعبة تتلاقي وهتحتاج تتغير قريب", "المحل مش بيقدر يصلح الموديل ده أصلاً"], "answer": "بطارية الموديل ده بقت صعبة تتلاقي وهتحتاج تتغير قريب", "rationale": "قالت «la batería de este modelo ya no se encuentra fácil» وإن ده هيبقى مصروف تاني قريب. التصليح نفسه ممكن، بس مش أذكى قرار."}, {"q": "ليه باكو شك إن الفنية عايزة تبيعله؟", "options": ["عشان نصحته يشتري موبايل جديد بدل التصليح", "عشان قالتله الموبايل ده مش بيتصلح خالص", "عشان طلبت منه يدفع عربون مقدم"], "answer": "عشان نصحته يشتري موبايل جديد بدل التصليح", "rationale": "سألها «¿no me estará vendiendo la moto?» وده تعبير إسباني معناه: بتضحكي عليّا؟ ردت «aquí solo reparamos, no vendemos móviles» يعني المحل بيصلح بس، فمش مستفيدة حاجة لو مشي من غير تصليح."}, {"q": "قرار باكو النهائي إيه؟", "options": ["هيصلح الشاشة فورًا في نفس اليوم", "هيغير البطارية بس ويسيب الشاشة", "مش هيصلح وهيشتري موبايل جديد"], "answer": "مش هيصلح وهيشتري موبايل جديد", "rationale": "قال «me ha convencido. Entonces no hace falta el arreglo» يعني اتقنع وملغاش التصليح."}, {"q": "آخر نصيحة الفنية كانت إيه؟", "options": ["يشتري نفس الموديل تاني لأنه مضمون", "ينقل الصور على الكمبيوتر قبل ما يرمي القديم", "يسيب الموبايل القديم عندها للفحص"], "answer": "ينقل الصور على الكمبيوتر قبل ما يرمي القديم", "rationale": "قالت «antes de tirar el viejo, pase las fotos al ordenador» يعني قبل ما ترمي القديم انقل الصور على الكمبيوتر. ماقالتش يشتري نفس الموديل."}]}, {"id": "b2-factura-telefono", "level": "B2", "title": "الفاتورة فيها غلط", "desc": "باكو راح شركة المحمول يعترض على فاتورة جت ضعف المعتاد، والموظفة بتحاول تحل المشكلة.", "lines": [{"speaker": "luna", "es": "Buenos días. ¿En qué puedo ayudarle?", "ar": "صباح الخير. أقدر أساعد حضرتك في إيه؟"}, {"speaker": "paco", "es": "Mire, este mes la factura me ha llegado del doble de lo normal, y no entiendo por qué.", "ar": "بصي، الشهر ده الفاتورة وصلتني ضعف المعتاد، ومش فاهم ليه."}, {"speaker": "luna", "es": "Vamos a verlo. ¿Me da su número, por favor? ... Aquí está. Efectivamente, hay un cargo de datos internacionales.", "ar": "خلينا نشوف. الرقم لو سمحت؟ ... أهو. فعلاً، فيه رسوم داتا دولية."}, {"speaker": "paco", "es": "¿Datos internacionales? Si yo no he salido de España este año.", "ar": "داتا دولية؟ أنا أصلًا مسافرتش برة إسبانيا السنة دي."}, {"speaker": "luna", "es": "A veces el móvil se conecta a una red extranjera si vive cerca de la frontera. ¿Ha estado cerca de Portugal o Francia?", "ar": "أحيانًا الموبايل بيتصل بشبكة أجنبية لو حضرتك ساكن قريب من الحدود. كنت قريب من البرتغال أو فرنسا؟"}, {"speaker": "paco", "es": "Vivo en Madrid. Esto es un error, claramente.", "ar": "أنا ساكن في مدريد. ده غلط واضح."}, {"speaker": "luna", "es": "Tiene razón, Madrid no tiene sentido. Le abro una reclamación ahora mismo y le devolvemos el importe en la próxima factura.", "ar": "مع حضرتك حق، مدريد ملهاش منطق. هفتحلك شكوى دلوقتي حالًا وهنرجعلك المبلغ في الفاتورة الجاية."}, {"speaker": "paco", "es": "¿En la próxima factura? Yo preferiría que me lo devolvieran ya. Es dinero que se me ha cobrado de más.", "ar": "في الفاتورة الجاية؟ كنت عايز تردوهالي دلوقتي. دي فلوس اتسحبت مني بالغلط."}, {"speaker": "luna", "es": "Lo entiendo, pero el sistema solo permite el abono en factura. Lo que sí puedo hacer es que se anote como prioridad, para que no se retrase.", "ar": "فاهماك، بس النظام بيسمح بالخصم في الفاتورة بس. اللي أقدر أعمله إني أسجله أولوية عشان ما يتأخرش."}, {"speaker": "paco", "es": "Vale, pero quiero un número de referencia y algo por escrito.", "ar": "ماشي، بس عايز رقم مرجع وحاجة مكتوبة."}, {"speaker": "luna", "es": "Por supuesto. Aquí tiene: es la referencia erre-cuatro-cero-dos-uno-cinco. Y le llegará un correo de confirmación hoy.", "ar": "أكيد. اتفضل: الرقم المرجعي أر-أربعة-صفر-اتنين-واحد-خمسة. وهيوصلك إيميل تأكيد النهارده."}, {"speaker": "paco", "es": "De acuerdo. Y si la próxima factura llega sin el abono, ¿qué hago?", "ar": "ماشي. ولو الفاتورة الجاية وصلت من غير الخصم، أعمل إيه؟"}, {"speaker": "luna", "es": "Llame al número de atención y dé esa referencia. Con eso recuperan todo el trámite en un minuto.", "ar": "اتصل بخدمة العملاء وقولهم الرقم ده. بيه هيوصلوا لكل تفاصيل الشكوى في دقيقة."}, {"speaker": "paco", "es": "Perfecto. Gracias por su ayuda.", "ar": "تمام. شكرًا على مساعدتك."}], "questions": [{"q": "مشكلة باكو إيه بالظبط؟", "options": ["الموبايل بتاعه اتكسر ومحتاج يتغير بضمان", "الفاتورة جت ضعف المعتاد بسبب رسوم داتا دولية", "عايز يغيّر باقته لباقة أرخص قبل السفر"], "answer": "الفاتورة جت ضعف المعتاد بسبب رسوم داتا دولية", "rationale": "قال «la factura me ha llegado del doble» والموظفة لقت «un cargo de datos internacionales». مفيش موبايل مكسور ولا تغيير باقة."}, {"q": "تفسير الموظفة الأول للرسوم كان إيه؟", "options": ["ممكن الموبايل اتصل بشبكة أجنبية لو ساكن قريب من الحدود", "الشركة غيّرت أسعارها من أول الشهر من غير تحذير", "باكو أكيد مسافر برة إسبانيا ونسي يقفل الداتا"], "answer": "ممكن الموبايل اتصل بشبكة أجنبية لو ساكن قريب من الحدود", "rationale": "قالت «el móvil se conecta a una red extranjera si vive cerca de la frontera». ولما عرفت إنه ساكن مدريد قالت إن ده ملهوش منطق."}, {"q": "الحل اللي اتفقوا عليه؟", "options": ["فلوس ناقصة ترجعله كاش في نفس الزيارة", "تغيير الباقة لباقة أعلى كتعويض عن الغلط", "شكوى برقم مرجع وخصم المبلغ من الفاتورة الجاية"], "answer": "شكوى برقم مرجع وخصم المبلغ من الفاتورة الجاية", "rationale": "قالت «Le abro una reclamación» و«le devolvemos el importe en la próxima factura». باكو طلب الفلوس فورًا بس النظام بيسمح بالخصم من الفاتورة بس."}, {"q": "ليه الموظفة ماقدرتش ترجع الفلوس فورًا؟", "options": ["مش معاها صلاحية ترجع أي مبلغ من غير مديرها", "النظام بيسمح بالخصم في الفاتورة بس", "لازم باكو يبعت طلب مكتوب على الإيميل الأول"], "answer": "النظام بيسمح بالخصم في الفاتورة بس", "rationale": "قالت «el sistema solo permite el abono en factura». مفيش كلام عن صلاحيات ولا إيميل."}, {"q": "باكو طلب إيه كضمان؟", "options": ["رقم مرجع وتأكيد مكتوب يوصله النهارده", "توقيع من مدير الفرع على ورقة رسمية", "خصم على الشهرين الجايين كمان زيادة"], "answer": "رقم مرجع وتأكيد مكتوب يوصله النهارده", "rationale": "قال «quiero un número de referencia y algo por escrito» وخد الرقم المرجعي ووعد بإيميل تأكيد النهارده."}, {"q": "لو الفاتورة الجاية جت من غير الخصم، يعمل إيه؟", "options": ["يلغي الخط خالص وينقل رقمه لشركة تانية", "يقدّم شكوى جديدة من الأول من غير رقم", "يكلم خدمة العملاء ويديهم رقم المرجع"], "answer": "يكلم خدمة العملاء ويديهم رقم المرجع", "rationale": "قالتله «Llame al número de atención y dé esa referencia» وهما هيوصلوا لكل تفاصيل الشكوى في دقيقة."}]}, {"id": "b2-proyecto-retrasado", "level": "B2", "title": "المشروع اتأخر", "desc": "لونا مديرة مشروع وبتكلم باكو عن تأخير التسليم: إيه السبب وإيه الخطة الواقعية للحاق.", "lines": [{"speaker": "luna", "es": "Paco, tenemos que hablar del proyecto. El cliente me ha llamado dos veces esta semana.", "ar": "يا باكو، لازم نتكلم في المشروع. العميل كلمّني مرتين الأسبوع ده."}, {"speaker": "paco", "es": "Ya me lo imagino. Mira, el retraso no es por falta de trabajo, es que los cambios que pidió el cliente nos han llevado una semana entera.", "ar": "متخيل. بصي، التأخير مش بسبب إننا مش شغالين، ده لأن التعديلات اللي العميل طلبها خدت مننا أسبوع كامل."}, {"speaker": "luna", "es": "Lo sé, y por eso quiero que lo veamos juntos. Si entregáramos lo que hay ahora, ¿qué faltaría?", "ar": "عارفة، وعشان كده عايزة نشوفه سوا. لو سلّمنا اللي موجود دلوقتي، إيه اللي هينقص؟"}, {"speaker": "paco", "es": "Faltaría la parte de informes y las pruebas finales. Sin eso, el cliente no puede usar el sistema solo.", "ar": "هينقص جزء التقارير والاختبارات النهائية. من غيرهم، العميل مش هيقدر يستخدم النظام لوحده."}, {"speaker": "luna", "es": "Vale. ¿Cuánto tiempo necesitas de verdad? No quiero fechas bonitas, quiero fechas reales.", "ar": "ماشي. محتاج قد إيه بجد؟ مش عايزة مواعيد شكلها حلو، عايزة مواعيد حقيقية."}, {"speaker": "paco", "es": "Si me quitas las reuniones de esta semana, termino los informes el jueves. Las pruebas, tres días laborables más.", "ar": "لو شيلتي الاجتماعات من على دماغي الأسبوع ده، هخلّص التقارير الخميس. والاختبارات تلات أيام شغل كمان."}, {"speaker": "luna", "es": "O sea, el martes de la semana que viene.", "ar": "يعني التلات الأسبوع الجاي."}, {"speaker": "paco", "es": "El martes, sí. Y si surge algún imprevisto, el miércoles como mucho.", "ar": "التلات، أيوه. ولو حصل أي ظرف، الأربع كحد أقصى."}, {"speaker": "luna", "es": "Entonces le digo al cliente miércoles. Prefiero dar un día más y cumplir, que dar el martes y fallar.", "ar": "يبقى هقول للعميل الأربع. أحسن أديله يوم زيادة وأوفي، بدل ما أقول التلات وأتأخر."}, {"speaker": "paco", "es": "De acuerdo. Y otra cosa: estaría bien que le explicaras al cliente que los cambios tienen un coste de tiempo, para la próxima.", "ar": "ماشي. وحاجة تانية: ياريت تشرحي للعميل إن التعديلات بتاخد وقت، عشان المرة الجاية."}, {"speaker": "luna", "es": "Tienes razón. Voy a preparar un resumen de los cambios y sus fechas, así lo ve claro.", "ar": "معاك حق. هجهز ملخص بالتعديلات وتواريخها، كده هيشوف الصورة واضحة."}, {"speaker": "paco", "es": "Perfecto. Entonces, sin reuniones esta semana, ¿eh?", "ar": "تمام. يبقى من غير اجتماعات الأسبوع ده، صح؟"}, {"speaker": "luna", "es": "Sin reuniones. Pero el jueves quiero ver los informes terminados.", "ar": "من غير اجتماعات. بس يوم الخميس عايزة أشوف التقارير خلصت."}], "questions": [{"q": "سبب التأخير حسب باكو؟", "options": ["ناس من الفريق ماكانوش شغالين كويس الفترة اللي فاتت", "الفريق كان مشغول بمشاكل في الأجهزة طول الأسبوع", "تعديلات العميل خدت من الفريق أسبوع كامل"], "answer": "تعديلات العميل خدت من الفريق أسبوع كامل", "rationale": "قال «los cambios que pidió el cliente nos han llevado una semana entera» ونفى إن السبب قلة شغل."}, {"q": "إيه اللي ناقص في المشروع؟", "options": ["موافقة العميل على الخطة الأساسية", "جزء التقارير والاختبارات النهائية", "التصميم لسه ما اتعملش من الأول"], "answer": "جزء التقارير والاختبارات النهائية", "rationale": "قال «Faltaría la parte de informes y las pruebas finales». التصميم وموافقة العميل ما اتذكروش كحاجة ناقصة."}, {"q": "لونا طلبت إيه من باكو لما سألته عن الوقت؟", "options": ["مواعيد حقيقية مش مواعيد شكلها حلو", "وعد إنه يخلص كل حاجة قبل بكرة", "تقرير مكتوب يبعته للعميل بنفسه"], "answer": "مواعيد حقيقية مش مواعيد شكلها حلو", "rationale": "قالت «No quiero fechas bonitas, quiero fechas reales» يعني عايزة مواعيد حقيقية مش للشكل."}, {"q": "ليه لونا قالت للعميل الأربع مش التلات؟", "options": ["عشان العميل قال إنه مش فاضي يوم التلات أصلاً", "عشان باكو طلب يوم أجازة في نص الأسبوع", "عشان تسيب هامش لو حصل ظرف وتفضل وافية بوعدها"], "answer": "عشان تسيب هامش لو حصل ظرف وتفضل وافية بوعدها", "rationale": "قالت «Prefiero dar un día más y cumplir, que dar el martes y fallar» يعني تفضل تدي يوم زيادة وتوفي."}, {"q": "باكو طلب من لونا تعمل إيه مع العميل للمستقبل؟", "options": ["تطلب منه فلوس زيادة عن كل تعديل جديد", "تشرحله إن التعديلات بتاخد وقت", "تبلغه إن الفريق زهقان من كتر التعديلات"], "answer": "تشرحله إن التعديلات بتاخد وقت", "rationale": "قال «estaría bien que le explicaras al cliente que los cambios tienen un coste de tiempo» يعني التعديلات بتاخد وقت."}, {"q": "المقايضة اللي حصلت في الآخر؟", "options": ["لونا شالت الاجتماعات مقابل التقارير جاهزة الخميس", "باكو يشتغل يوم الأجازة مقابل مكافأة مالية", "العميل يستنى أسبوعين كاملين زيادة من غير شكوى"], "answer": "لونا شالت الاجتماعات مقابل التقارير جاهزة الخميس", "rationale": "باكو اشترط «Si me quitas las reuniones... termino los informes el jueves» ولونا أكدت: «Sin reuniones. Pero el jueves quiero ver los informes terminados»."}]}, {"id": "b2-cancelacion-hotel", "level": "B2", "title": "إلغاء حجز الفندق", "desc": "لونا عندها ظرف اضطراري وعايزة تلغي حجز غير قابل للاسترداد، وبتحاول توصل لحل عادل مع موظف الاستقبال.", "lines": [{"speaker": "paco", "es": "Recepción, buenas tardes.", "ar": "الاستقبال، مساء الخير."}, {"speaker": "luna", "es": "Buenas tardes. Tengo una reserva para este fin de semana y necesito cancelarla. Me ha surgido un problema familiar.", "ar": "مساء الخير. عندي حجز آخر الأسبوع ده ومحتاجة ألغيه. حصلتلي ظروف عائلية."}, {"speaker": "paco", "es": "Lo siento mucho. Déjeme ver... Sí, aquí está. Le comento que su tarifa es no reembolsable, se lo indicaba la confirmación.", "ar": "متأسف أوي. خليني أشوف... أيوه، لقيته. حابب أوضّحلك إن حجز حضرتك غير قابل للاسترداد، وده كان مكتوب في التأكيد."}, {"speaker": "luna", "es": "Sí, lo sé, lo vi. Pero pensé que, siendo un problema familiar, podrían hacer una excepción.", "ar": "أيوه عارفة، شفته. بس كنت فاكرة إن طالما الظروف عائلية، ممكن تعملوا استثناء."}, {"speaker": "paco", "es": "Entiendo perfectamente su situación. Mire, una devolución completa no puedo autorizarla yo, pero hay una opción que igual le interesa.", "ar": "فاهم ظرفك تمامًا. بصي، استرداد كامل أنا مش عندي صلاحية أعمله، بس فيه حل ممكن يعجبك."}, {"speaker": "luna", "es": "Dígame.", "ar": "اتفضل، سامعاك."}, {"speaker": "paco", "es": "Puedo cambiarle la reserva a cualquier fin de semana de los próximos seis meses, sin coste adicional. Así no pierde el dinero.", "ar": "أقدر أنقل الحجز لأي ويك إند في الست شهور الجايين، من غير أي تكلفة زيادة. كده فلوسك مش هتضيع."}, {"speaker": "luna", "es": "¿Y si el fin de semana que elija es más caro?", "ar": "ولو الويك إند اللي هختاره أغلى؟"}, {"speaker": "paco", "es": "Pagaría solo la diferencia. Si es más barato, se lo dejamos como crédito para el desayuno o el parking.", "ar": "هتدفعي الفرق بس. ولو أرخص، هنسيبلك الفرق رصيد للفطار أو الجراج."}, {"speaker": "luna", "es": "Hmm. ¿Y no hay manera de que me devuelvan al menos la mitad? Prefiero el dinero, la verdad, porque no sé cuándo podré viajar.", "ar": "همم. ومفيش طريقة ترجعولي ولو النص؟ أنا بصراحة أحب آخد الفلوس، لأني مش عارفة هقدر أسافر إمتى."}, {"speaker": "paco", "es": "Le voy a ser sincero: con esa tarifa, la mitad tampoco está en mi mano. Lo que sí puedo hacer es anotar su caso y que la dirección lo revise mañana. No le prometo nada, pero se lo paso con buena recomendación.", "ar": "هكون صريح معاكي: على الحجز ده، حتى النص مش في إيدي. اللي أقدر أعمله إني أسجل حالتك والإدارة تراجعها بكرة. مش بوعدك بحاجة، بس هقدمها بتوصية كويسة."}, {"speaker": "luna", "es": "Vale. Hágalo, por favor. ¿Y si dicen que no, me queda la opción del cambio de fechas?", "ar": "ماشي. اعمل كده لو سمحت. ولو قالوا لأ، يفضل معايا اختيار تغيير المعاد؟"}, {"speaker": "paco", "es": "Exacto, esa opción sigue disponible durante seis meses. Le llamo mañana antes de las doce con la respuesta.", "ar": "بالظبط، الاختيار ده هيفضل متاح طول الست شهور. هكلمك بكرة قبل الساعة اتناشر بالرد."}, {"speaker": "luna", "es": "De acuerdo. Gracias por la claridad, de verdad.", "ar": "ماشي. شكرًا على الوضوح، بجد."}], "questions": [{"q": "نوع حجز لونا إيه؟", "options": ["مجاني كجزء من عرض خاص للعملاء القدامى", "قابل للاسترداد بالكامل لأنها حجزت بدري", "غير قابل للاسترداد، وده كان مكتوب في التأكيد"], "answer": "غير قابل للاسترداد، وده كان مكتوب في التأكيد", "rationale": "الموظف قال «su tarifa es no reembolsable» وإن ده كان مكتوب في التأكيد، ولونا اعترفت إنها شافته."}, {"q": "الحل الأول اللي الموظف عرضه؟", "options": ["ترقية الغرفة لجناح في نفس المعاد", "نقل الحجز لأي ويك إند خلال ست شهور من غير تكلفة", "استرداد كامل للمبلغ على نفس الكارت فورًا"], "answer": "نقل الحجز لأي ويك إند خلال ست شهور من غير تكلفة", "rationale": "قال «Puedo cambiarle la reserva a cualquier fin de semana de los próximos seis meses, sin coste adicional»."}, {"q": "لو الموعد الجديد أرخص، هيحصل إيه للفرق؟", "options": ["يتحول لرصيد ليها للفطار أو الجراج", "الفرق بيضيع ومش بيتحسب في حاجة", "يرجعلها كاش على الكارت في نفس اليوم"], "answer": "يتحول لرصيد ليها للفطار أو الجراج", "rationale": "قال «se lo dejamos como crédito para el desayuno o el parking» يعني الفرق رصيد للفطار أو الجراج."}, {"q": "ليه لونا مفضّلة الفلوس عن تغيير المعاد؟", "options": ["الفندق معجبهاش وعايزة تحجز في مكان تاني", "عايزة الفلوس عشان تدفع مصاريف تانية خالص", "مش عارفة هتقدر تسافر إمتى بسبب ظروفها"], "answer": "مش عارفة هتقدر تسافر إمتى بسبب ظروفها", "rationale": "قالت «no sé cuándo podré viajar» يعني مش عارفة هتقدر تسافر إمتى. مفيش كلام عن فندق تاني."}, {"q": "إيه اللي الموظف قدر يعمله بجد؟", "options": ["وعدها إنه هيرجعلها نص المبلغ أكيد بكرة", "سجّل الحالة والإدارة هتراجعها بكرة من غير أي وعد", "رجعلها كل الفلوس من خزنة الفرع فورًا"], "answer": "سجّل الحالة والإدارة هتراجعها بكرة من غير أي وعد", "rationale": "قال «No le prometo nada, pero se lo paso con buena recomendación» يعني مش هيوعدها بحاجة مش في إيده، بس هيوصّل طلبها."}, {"q": "لحد إمتى اختيار تغيير المعاد متاح؟", "options": ["يفضل متاح طول الست شهور حتى لو الإدارة رفضت", "متاح لمدة أسبوع واحد بس من تاريخ المكالمة", "لازم تقرر في نفس المكالمة وإلا هتخسره"], "answer": "يفضل متاح طول الست شهور حتى لو الإدارة رفضت", "rationale": "قال «esa opción sigue disponible durante seis meses» وأكد إنه لو الإدارة قالت لأ، الاختيار هيفضل موجود."}]}, {"id": "b2-entrevista-trabajo", "level": "B2", "title": "سؤال صعب في المقابلة", "desc": "باكو في مقابلة شغل ولونا المديرة بتسأله عن فترة الفراغ في سيرته الذاتية.", "lines": [{"speaker": "luna", "es": "Su experiencia es muy interesante, pero me llama la atención una cosa: hay un año entero sin trabajar entre sus dos últimos empleos. ¿Puede contarme qué pasó?", "ar": "خبرتك مثيرة للاهتمام جدًا، بس فيه حاجة واخدة بالي: فيه سنة كاملة من غير شغل بين آخر وظيفتين. ممكن تحكيلي إيه اللي حصل؟"}, {"speaker": "paco", "es": "Claro. La empresa donde trabajaba cerró y me quedé sin empleo. Los primeros meses busqué trabajo sin parar, pero el sector estaba parado.", "ar": "أكيد. الشركة اللي كنت شغال فيها قفلت ولقيت نفسي من غير شغل. أول شهور كنت بدور على شغل من غير توقف، بس المجال كان واقف."}, {"speaker": "luna", "es": "¿Y el resto del año?", "ar": "وباقي السنة؟"}, {"speaker": "paco", "es": "Mi madre enfermó y decidí cuidarla. Podía permitírmelo unos meses, y era más importante para mí que aceptar cualquier trabajo rápido.", "ar": "والدتي تعبت وقررت أقعد جنبها. كنت أقدر أتحمل ده ماديًا كام شهر، وده كان أهم ليا من إني أقبل أي شغل بسرعة."}, {"speaker": "luna", "es": "Entiendo. Algunos entrevistadores verían eso como un riesgo: que usted deje el trabajo si surge algo personal.", "ar": "فاهمة. فيه مسؤولين توظيف ممكن يشوفوا ده خطر: إنك تسيب الشغل لو حصلك ظرف شخصي."}, {"speaker": "paco", "es": "Yo lo veo al revés: volví en cuanto mi madre mejoró, y en mi trabajo actual pasé cuatro años sin faltar apenas. Sé separar las cosas, pero también sé qué es lo importante.", "ar": "أنا شايفه بالعكس: أول ما والدتي اتحسّنت رجعت للشغل، وفي شغلي الحالي اشتغلت أربع سنين من غير غياب تقريبًا. أعرف أفصل بين الحاجات وعارف إيه المهم."}, {"speaker": "luna", "es": "Bien dicho. Otra pregunta: ¿por qué quiere dejar su trabajo actual?", "ar": "كلام جميل. سؤال تاني: ليه عايز تسيب شغلك الحالي؟"}, {"speaker": "paco", "es": "Porque he llegado al techo. Aprendí todo lo que podía aprender allí, y su empresa trabaja en proyectos que allí no existen.", "ar": "لأني وصلت لآخر ما أقدر أوصله هناك. اتعلمت كل اللي ممكن أتعلمه هناك، وشركتك بتشتغل على مشاريع مش موجودة هناك."}, {"speaker": "luna", "es": "¿Y si le ofrecieran allí más dinero para quedarse?", "ar": "ولو عرضوا عليك هناك فلوس أكتر عشان تفضل؟"}, {"speaker": "paco", "es": "Le seré sincero: el dinero importa, pero si fuera solo eso, ya me habría ido a cualquier otro sitio. Lo que busco es crecer, y eso aquí lo veo claro.", "ar": "هكون صريح معاك: الفلوس مهمة، بس لو كانت بس الفلوس، كنت مشيت لأي مكان تاني من زمان. اللي بدور عليه إني أكبر، وده شايفه واضح عندكم."}, {"speaker": "luna", "es": "Muy bien. Nosotros también vamos a ser sinceros con usted: hay otros dos candidatos. Le llamaremos el viernes, sea cual sea la decisión.", "ar": "جميل أوي. إحنا كمان هنكون صريحين معاك: فيه مرشحين اتنين تانيين. هنكلمك يوم الجمعة، مهما كان القرار."}, {"speaker": "paco", "es": "Se lo agradezco. Prefiero un no claro a semanas de espera.", "ar": "بشكرك عليه. أحسن عندي رفض واضح من إني أستنى أسابيع."}], "questions": [{"q": "سبب سنة الفراغ في سيرة باكو؟", "options": ["شركته قفلت وبعدين والدته تعبت فقعد جنبها", "قعد سنة يدرس كورسات عشان يغيّر مجاله المهني خالص", "خد سنة أجازة عشان يسافر حوالين العالم ويرتاح من الشغل"], "answer": "شركته قفلت وبعدين والدته تعبت فقعد جنبها", "rationale": "قال «La empresa... cerró» وبعدين «Mi madre enfermó y decidí cuidarla». سفر ودراسة ما اتذكروش."}, {"q": "لونا ردت على إجابته إزاي؟", "options": ["تجاهلت الموضوع خالص وكملت في السيرة الذاتية", "قالتله المقابلة خلصت وشكرته على وقته", "واجهته بإن في مسؤولين توظيف ممكن يشوفوا ده خطر"], "answer": "واجهته بإن في مسؤولين توظيف ممكن يشوفوا ده خطر", "rationale": "قالت «Algunos entrevistadores verían eso como un riesgo» يعني في ناس ممكن تشوف ده خطر."}, {"q": "باكو دافع عن نفسه إزاي؟", "options": ["قال إن ده موضوع شخصي ومش من حقها تسأل فيه أصلًا", "رجع يشتغل أول ما والدته اتحسّنت وأربع سنين ما غابش تقريبًا", "وعدها إنه مش هيسيب الشغل الجديد مهما كانت الظروف"], "answer": "رجع يشتغل أول ما والدته اتحسّنت وأربع سنين ما غابش تقريبًا", "rationale": "قال «volví en cuanto mi madre mejoró» و«pasé cuatro años sin faltar apenas»."}, {"q": "ليه باكو عايز يسيب شغله الحالي؟", "options": ["وصل لآخر ما يقدر يوصله هناك وعايز يكبر", "مرتبه قليل جدًا مقارنة بزمايله في نفس الشركة", "عنده مشاكل شخصية مع مديره المباشر من زمان"], "answer": "وصل لآخر ما يقدر يوصله هناك وعايز يكبر", "rationale": "قال «he llegado al techo» و«Lo que busco es crecer». صرح إن الفلوس مهمة بس مش هي السبب الأساسي."}, {"q": "رد باكو على سؤال «لو عرضوا عليك فلوس أكتر تفضل؟»", "options": ["رفض يجاوب على السؤال وقال ده موضوع شخصي", "هيقبل أي عرض أعلى فورًا من غير تفكير", "الفلوس مهمة بس اللي بيدور عليه إنه يكبر، وده شايفه عندهم"], "answer": "الفلوس مهمة بس اللي بيدور عليه إنه يكبر، وده شايفه عندهم", "rationale": "قال «el dinero importa, pero... Lo que busco es crecer, y eso aquí lo veo claro»."}, {"q": "إيه اللي وعدت بيه لونا في الآخر؟", "options": ["هتكلمّه بعد شهر لما تخلص كل المقابلات", "هتكلمّه يوم الجمعة مهما كان القرار، وقالتله في مرشحين تانيين", "الوظيفة بتاعته خلاص والتعاقد بعد أسبوع"], "answer": "هتكلمّه يوم الجمعة مهما كان القرار، وقالتله في مرشحين تانيين", "rationale": "قالت «Le llamaremos el viernes, sea cual sea la decisión» يعني هتكلمّه الجمعة مهما كان القرار. ما وعدتوش بالوظيفة."}]}, {"id": "c1-vecino-ruido", "level": "C1", "title": "الجار والموسيقى", "desc": "باكو بيخبط على لونا بسبب صوت الموسيقى، وكل واحد بيحاول يعدّي رسالته من غير ما يخسر وشه.", "lines": [{"speaker": "paco", "es": "Buenas noches, Luna. Perdona la hora.", "ar": "مساء الخير يا لونا. آسف إني جاي في الوقت ده."}, {"speaker": "luna", "es": "Hola, Paco. ¿Pasa algo?", "ar": "أهلًا يا باكو. في حاجة؟"}, {"speaker": "paco", "es": "No es nada grave, pero... la música se oye bastante en mi salón. Tengo una reunión temprano mañana.", "ar": "مفيش حاجة كبيرة، بس... الموسيقى مسموعة أوي عندي في الصالون. عندي اجتماع بدري بكرة."}, {"speaker": "luna", "es": "Ay, lo siento, no me había dado cuenta de que se oía tanto. Es el cumpleaños de mi hermana, ya ves.", "ar": "آه آسفة، ماخدتش بالي إن الصوت واصل كده. عيد ميلاد أختي، زي ما إنت شايف."}, {"speaker": "paco", "es": "Claro, claro, y ni se me pasa por la cabeza pedirte que cortes la fiesta. Ahora bien, si la bajaras un poco a partir de las doce, te lo agradecería de verdad.", "ar": "أكيد أكيد، ومش جاي في بالي أطلب منك تقفّي الحفلة. بس لو وطّيتي الصوت شوية بعد الساعة اتناشر، هبقى ممنون ليكي بجد."}, {"speaker": "luna", "es": "Hecho. Y perdona que te lo diga, pero la última vez que tuviste invitados tú, yo no dije nada, ¿eh?", "ar": "اتفقنا. وسامحني إني أقولها، بس آخر مرة كان عندك ضيوف إنت، أنا مقلتش حاجة، صح؟"}, {"speaker": "paco", "es": "Tienes toda la razón, y te lo agradezco. Por eso vengo yo primero y en buen plan, en vez de llamar a la policía como haría otro.", "ar": "معاكي كل الحق، وبشكرك عليه. عشان كده أنا جاي بنفسي وبكل طيبة، بدل ما أكلم الشرطة زي ما حد تاني كان هيعمل."}, {"speaker": "luna", "es": "Y yo te agradezco que vengas tú y no tu mujer, que la última vez casi me grita por el buzón.", "ar": "وأنا بشكرك إنك إنت اللي جيت مش مراتك، لأنها المرة اللي فاتت كانت هتزعقلي في وشي بسبب صندوق البريد."}, {"speaker": "paco", "es": "Ja, ja. Bueno, cada uno tiene su carácter. Entonces, ¿a las doce?", "ar": "ههه. طيب، كل واحد وليه طباعه. يبقى اتفقنا، الساعة اتناشر؟"}, {"speaker": "luna", "es": "A las doce bajo la música y, para que puedas dormir, a la una apagamos del todo. Te invito a un trozo de tarta, por cierto.", "ar": "الساعة اتناشر هوطّي الموسيقى، وعشان تقدر تنام، الساعة واحدة هنقفل خالص. بالمناسبة، تعالى خدلك قطعة تورتة."}, {"speaker": "paco", "es": "Eso sí que es un buen final. Cinco minutos, que me quito el pijama.", "ar": "ده بقى ختام حلو. خمس دقايق وأغير هدومي وأجي."}], "questions": [{"q": "باكو عبّر عن شكواه إزاي؟", "options": ["زعق في الباب من الأول من غير مقدمات ولا سلام", "بهدوء وادّى سبب عملي، إنه عنده اجتماع بدري", "كلم الشرطة فورًا وبلّغ عن الإزعاج"], "answer": "بهدوء وادّى سبب عملي، إنه عنده اجتماع بدري", "rationale": "قال «No es nada grave, pero...» ودي صيغة تهذيب بتخفف الشكوى، وذكر الاجتماع كسبب. مفيش زعيق ولا شرطة."}, {"q": "رد لونا الأول كان إيه؟", "options": ["اتهمته إنه بيكبّر الموضوع قصد", "قفلت الباب في وشه من غير كلمة ولا رد", "اعتذرت وقالت إنه عيد ميلاد أختها"], "answer": "اعتذرت وقالت إنه عيد ميلاد أختها", "rationale": "قالت «lo siento, no me había dado cuenta» و«Es el cumpleaños de mi hermana». مفيش تصعيد من ناحيتها."}, {"q": "ليه لونا فكّرته بضيوفه هو؟", "options": ["عشان توازن المعاملة: هي سكتت لما كان عنده ضيوف", "عشان تتهمه بالنفاق وتقطع الكلام معاه", "عشان ترفض طلبه خالص من غير سبب"], "answer": "عشان توازن المعاملة: هي سكتت لما كان عنده ضيوف", "rationale": "قالت «la última vez que tuviste invitados tú, yo no dije nada» ووافقت على طلبه، فده مش رفض."}, {"q": "إيه اللي بيلمّح له باكو بجملة الشرطة؟", "options": ["إنه هددها إنه هيكلم الشرطة لو ماسكتتش", "إنه بيشتكي من جار تاني في العمارة", "إنه اختار الحل الودي بدل التصعيد، وده يتحسب له"], "answer": "إنه اختار الحل الودي بدل التصعيد، وده يتحسب له", "rationale": "«vengo yo primero y en buen plan, en vez de llamar a la policía como haría otro» تلميح مش تهديد: بيقولها إنه اختار الطريق الودي."}, {"q": "الاتفاق النهائي إيه؟", "options": ["الحفلة هتقفل فورًا من دلوقتي", "الصوت يوطّى اتناشر والحفلة تقفل واحدة، وباكو رايح ياخد قطعة تورتة", "لونا هتتجاهل الشكوى وتكمل سهرة عادي"], "answer": "الصوت يوطّى اتناشر والحفلة تقفل واحدة، وباكو رايح ياخد قطعة تورتة", "rationale": "باكو قال من الأول «ni se me pasa por la cabeza pedirte que cortes la fiesta» يعني مش ناوي يطلب منها تقفل الحفلة، ولونا قالت «A las doce bajo la música... a la una apagamos» ودعته على التورتة."}, {"q": "المفاجأة في آخر الحوار إيه؟", "options": ["باكو قبل دعوة التورتة وراح يغير هدومه", "باكو رفض الدعوة ومشي متضايق من غير ما يقول حاجة", "لونا رجعت في كلامها وقفلت الحفلة في نصها"], "answer": "باكو قبل دعوة التورتة وراح يغير هدومه", "rationale": "قال «Eso sí que es un buen final. Cinco minutos, que me quito el pijama» يعني قبل الدعوة وراح يغير هدومه."}]}, {"id": "c1-quien-lidera", "level": "C1", "title": "مين يقود المشروع؟", "desc": "لونا وباكو بيتفاوضوا بأدب على مين يقود المشروع الجديد، كل واحد من غير ما يقولها صراحة.", "lines": [{"speaker": "luna", "es": "Gracias a todos por venir. Como saben, el proyecto Andalucía arranca el mes que viene y hay que nombrar un responsable.", "ar": "شكرًا لحضوركم. زي ما انتوا عارفين، مشروع أندلسيا هيبدأ الشهر الجاي ولازم نعيّن مسؤول."}, {"speaker": "paco", "es": "Si me permites, Luna: yo llevo dos años con este cliente y conozco sus manías. Sería una pena perder ese conocimiento.", "ar": "لو تسمحيلي يا لونا: أنا شغال مع العميل ده سنتين وعارف دماغه كويس. هيبقى خسارة نضيّع الخبرة دي."}, {"speaker": "luna", "es": "Claro, Paco, por muy valioso que sea ese conocimiento, y lo es, y contaremos contigo sí o sí, la pregunta es quién coordina.", "ar": "أكيد يا باكو، مهما كانت خبرتك قيّمة، وهي فعلاً قيّمة وهنعتمد عليك أكيد، السؤال مين اللي هينسّق."}, {"speaker": "paco", "es": "Pues eso es lo que digo: coordinar con un cliente que ya conoces es mucho más fácil que empezar de cero.", "ar": "وده اللي بقوله: إنك تنسّق مع عميل تعرفه أسهل بكتير من إنك تبدأ من الصفر."}, {"speaker": "luna", "es": "Totalmente de acuerdo. Aunque también hay que pensar en la carga: tú ya llevas el proyecto Norte y el mantenimiento. No querríamos quemarte.", "ar": "متفقة معاك تمامًا. بس برضه لازم نفكر في الضغط اللي عليك: إنت شايل مشروع الشمال والصيانة. مش عايزين نرهقك."}, {"speaker": "paco", "es": "Te agradezco la preocupación, aunque prefiero decidir yo si puedo con más o no.", "ar": "بشكرك على اهتمامك، بس أنا أحب أقرر بنفسي لو أقدر آخد أكتر ولا لأ."}, {"speaker": "luna", "es": "Por supuesto. Solo lo menciono porque el año pasado, cuando acumulaste tres proyectos, el cliente Norte se quejó de los tiempos.", "ar": "أكيد. أنا بس بقول كده عشان السنة اللي فاتت، لما شلت تلات مشاريع مع بعض، عميل الشمال اشتكى من المواعيد."}, {"speaker": "paco", "es": "Y precisamente por eso aprendí a organizarme mejor. Los errores de los que se aprende se llaman experiencia, ¿no?", "ar": "وبالظبط عشان كده اتعلمت أنظم نفسي أحسن. الغلطات اللي الواحد بيتعلم منها اسمها خبرة، صح؟"}, {"speaker": "luna", "es": "Sin duda. Mira, te propongo esto: tú lideras la relación con el cliente, que es tu fuerte, y yo coordino la parte interna. Así el proyecto tiene lo mejor de cada uno.", "ar": "من غير شك. بص، أنا هقترح عليك كده: إنت تقود علاقة العميل، دي نقطة قوتك، وأنا أنسّق الجزء الداخلي. كده المشروع هياخد أحسن حاجة من كل واحد فينا."}, {"speaker": "paco", "es": "Hmm. Oído. ¿Y a la hora de la verdad quién firma las entregas?", "ar": "همم. سامعك. وساعة الجد مين اللي هيمضي على التسليمات؟"}, {"speaker": "luna", "es": "Las firmamos los dos. Y si algún día hay que elegir, que elija el director. Pero sospecho que trabajando así no hará falta.", "ar": "إحنا الاتنين نمضي. ولو يوم لازم نختار، المدير يختار. بس عندي إحساس إننا لو مشينا كده مش هنحتاج."}, {"speaker": "paco", "es": "Trato hecho, entonces.", "ar": "يبقى اتفقنا."}], "questions": [{"q": "حجة باكو الأولى عشان يقود المشروع؟", "options": ["هو أقدم واحد في الشركة كلها من خمستاشر سنة", "هو صاحب فكرة المشروع من البداية خالص", "عارف العميل من سنتين وعارف دماغه كويس"], "answer": "عارف العميل من سنتين وعارف دماغه كويس", "rationale": "قال «llevo dos años con este cliente y conozco sus manías». الأقدمية والفكرة ما اتذكروش."}, {"q": "لونا ردت على حجته إزاي أول مرة؟", "options": ["أقرت بقيمة خبرته بس فرّقت بين المعرفة والتنسيق", "رفضت كلامه خالص وقالتله مش هتقود", "ادتله المشروع كله من غير نقاش"], "answer": "أقرت بقيمة خبرته بس فرّقت بين المعرفة والتنسيق", "rationale": "«por muy valioso que sea ese conocimiento... la pregunta es quién coordina» يعني مهما كانت خبرتك قيّمة، السؤال مين هينسّق."}, {"q": "لونا اعترضت على باكو بإيه؟", "options": ["هددته إنها هتكلم المدير في الموضوع", "فكّرته بشكوى عميل الشمال لما شال تلات مشاريع مع بعض", "قالتله إنت كبرت على المشاريع دي خلاص"], "answer": "فكّرته بشكوى عميل الشمال لما شال تلات مشاريع مع بعض", "rationale": "«el año pasado, cuando acumulaste tres proyectos, el cliente Norte se quejó» وقدمته كقلق عليه مش هجوم."}, {"q": "باكو رد إزاي على كلام لونا عن السنة اللي فاتت؟", "options": ["قال إن الغلطات اللي الواحد بيتعلم منها اسمها خبرة", "تجاهل الموضوع خالص وفتح في نقطة تانية عن ميزانية المشروع", "قال إن شكوى العميل ماكانتش حقيقية ومبالغ فيها"], "answer": "قال إن الغلطات اللي الواحد بيتعلم منها اسمها خبرة", "rationale": "«Los errores de los que se aprende se llaman experiencia» يعني الغلطات اللي اتعلم منها بقت خبرة."}, {"q": "الحل الوسط اللي اقترحته لونا؟", "options": ["هي تقود المشروع لوحدها من الألف للياء", "هو يقود المشروع لوحده من غير مساعدة", "هو يقود علاقة العميل وهي تنسّق الداخلي، والاتنين يمضوا على التسليمات"], "answer": "هو يقود علاقة العميل وهي تنسّق الداخلي، والاتنين يمضوا على التسليمات", "rationale": "«tú lideras la relación con el cliente... yo coordino la parte interna» و«Las firmamos los dos»."}, {"q": "ليه سأل باكو «¿Y a la hora de la verdad quién firma las entregas?»؟", "options": ["عشان عايز يعرف إيه موعد التسليم النهائي للمشروع ده", "عشان يعرف مين صاحب القرار الرسمي على التسليمات", "عشان خايف من الأوراق والتوقيعات الرسمية الكتير"], "answer": "عشان يعرف مين صاحب القرار الرسمي على التسليمات", "rationale": "سأل «¿Y a la hora de la verdad quién firma las entregas?» يعني ساعة الجد مين المسؤول رسميًا."}]}, {"id": "c1-amigo-impuntual", "level": "C1", "title": "صاحبي اللي بيتأخر دايمًا", "desc": "لونا قررت تواجه باكو بمشكلة تأخيره المزمن، بس من غير ما تكسر الصداقة.", "lines": [{"speaker": "luna", "es": "Por fin, ¿no? Te estaba esperando desde las ocho.", "ar": "أخيرًا، صح؟ أنا مستنياك من الساعة تمانية."}, {"speaker": "paco", "es": "Son las ocho y cuarto, mujer, tampoco es para tanto.", "ar": "الساعة تمنية والربع يا ستي، مش للدرجة دي برضه."}, {"speaker": "luna", "es": "Paco, quedamos a las ocho. Y la semana pasada fueron veinte minutos, y la anterior, media hora. Como para no llevar la cuenta.", "ar": "يا باكو، إحنا اتفقنا على الساعة تمانية. والأسبوع اللي فات كان عشرين دقيقة، واللي قبله نص ساعة. يعني إزاي مش هحسبها؟"}, {"speaker": "paco", "es": "Vale, ya veo por dónde vas. No es una queja, es un historial.", "ar": "ماشي، أنا فاهم إنتي رايحة فين. دي مش شكوى، دي كشف حساب."}, {"speaker": "luna", "es": "Es que me fastidia, de verdad. No es por los quince minutos, es que me hace sentir que mi tiempo vale menos que el tuyo.", "ar": "الموضوع بيزعلني بجد. مش عشان الربع ساعة، عشان بيحسسني إن وقتي أرخص من وقتك."}, {"speaker": "paco", "es": "Venga, no exageres. Sabes que no pienso eso.", "ar": "يا ستي ما تكبريش الموضوع. إنتي عارفة إني مش بفكر كده."}, {"speaker": "luna", "es": "Lo que piensas no lo sé, lo que veo es que siempre llegas tarde y siempre hay una razón buena. El tráfico, una llamada, lo que sea.", "ar": "بتفكر إيه مش عارفة، اللي شايفاه إنك دايمًا بتتأخر ودايمًا في سبب كويس. الزحمة، مكالمة، أي حاجة."}, {"speaker": "paco", "es": "Uf. Vale. Puede que tengas razón en una cosa: yo siempre calculo el tiempo justo, y siempre pasa algo.", "ar": "أوف. ماشي. ممكن يكون معاكي حق في حاجة: أنا دايمًا بحسب الوقت بالظبط، ودايمًا بيحصل حاجة."}, {"speaker": "luna", "es": "Pues cuenta con un margen, como hago yo contigo desde hace años, por cierto.", "ar": "طيب احسب حسابك بمعاد زيادة، زي ما أنا بعمل معاك من سنين، بالمناسبة."}, {"speaker": "paco", "es": "¿Cómo que como haces tú conmigo?", "ar": "يعني إيه زي ما إنتي بتعملي معايا؟"}, {"speaker": "luna", "es": "Pues que cuando quedamos a las ocho, yo sé que llegarás a las ocho y cuarto, así que yo salgo de casa para llegar a las ocho y diez. Y hoy, mira, hoy llegué a las ocho en punto para comprobarlo. Y aquí estoy, esperando.", "ar": "يعني لما نتفق على تمانية، أنا عارفة إنك هتوصل تمانية والربع، فبطلع من البيت بحيث أوصل تمانية وعشرة. والنهارده، بص، النهارده وصلت تمانية بالظبط عشان أتأكد. وأنا أهو مستنية."}, {"speaker": "paco", "es": "Es broma, ¿no? Llevas años llegando tarde a propósito para no esperarme.", "ar": "بتهزري، صح؟ إنتي من سنين بتتأخري عن قصد عشان متستنينيش."}, {"speaker": "luna", "es": "A propósito no, con conocimiento de causa. Que es distinto.", "ar": "مش عن قصد، لأ، عن دراية. وده شيء تاني."}, {"speaker": "paco", "es": "Ja, ja. Está bien, me has ganado. Ocho en punto la próxima vez. Y si llego tarde, pago la cena.", "ar": "ههه. خلاص، كسبتيني. تمانية بالظبط المرة الجاية. ولو اتأخرت، العشا عليّا."}, {"speaker": "luna", "es": "Apuntado. Y ya que estás, la de hoy también la pagas tú, que la espera ha sido larga.", "ar": "اتسجّل. وما دام كده، عشا النهارده كمان عليك، عشان الانتظار كان طويل."}, {"speaker": "paco", "es": "Negociadora nata. Venga, invito yo. Pero que conste que son las ocho y dieciséis.", "ar": "مفاوضة بالفطرة. ماشي، العشا عليّا. بس خدي بالك إن الساعة تمانية وستاشر دقيقة."}], "questions": [{"q": "شكوى لونا الحقيقية مش عن الوقت نفسه، عن إيه؟", "options": ["إن المكان اللي رايحينه بعيد أوي", "إنها جوعانة والمطعم هيقفل بدري", "الإحساس إن وقتها أرخص من وقته"], "answer": "الإحساس إن وقتها أرخص من وقته", "rationale": "قالت «me hace sentir que mi tiempo vale menos que el tuyo» يعني بيحسسها إن وقتها أرخص من وقته."}, {"q": "رد باكو الأول كان إزاي؟", "options": ["اعتذر ليها فورًا من أول كلمة وقال إنه غلطان", "قلّل من الموضوع: «مش للدرجة دي برضه» و«ما تكبريش»", "غيّر الموضوع خالص وكلمّها في حاجة تانية عن الشغل والصحبة"], "answer": "قلّل من الموضوع: «مش للدرجة دي برضه» و«ما تكبريش»", "rationale": "قال «tampoco es para tanto» و«no exageres» يعني مش للدرجة دي وما تكبريش الموضوع."}, {"q": "إيه الاعتراف الجزئي اللي باكو عمله؟", "options": ["إنه بيحسب الوقت بالظبط ودايمًا بيحصل حاجة", "إنه مش بيحترمها ولا بيحترم وقتها", "إنه عمره ما هيتغير مهما حصل"], "answer": "إنه بيحسب الوقت بالظبط ودايمًا بيحصل حاجة", "rationale": "«Puede que tengas razón en una cosa: yo siempre calculo el tiempo justo, y siempre pasa algo»."}, {"q": "كشف لونا الكبير كان إيه؟", "options": ["إنها كلمت أصحابهم المشتركين واشتكتلهم إنه دايمًا بيتأخر عنها", "إنها قررت تبطل تخرج معاه خالص مهما اعتذر", "إنها من سنين بتحسب تأخيره وبتطلع متأخرة عشان متستناهوش"], "answer": "إنها من سنين بتحسب تأخيره وبتطلع متأخرة عشان متستناهوش", "rationale": "«yo salgo de casa para llegar a las ocho y diez... hoy llegué a las ocho en punto para comprobarlo»."}, {"q": "الاتفاق النهائي إيه؟", "options": ["هيفضلوا الاتنين بيتأخروا زي ما هما", "المرة الجاية تمانية بالظبط، ولو اتأخر يدفع العشا، وعشا النهارده عليه", "لونا هتستناه من غير أي شكوى تاني"], "answer": "المرة الجاية تمانية بالظبط، ولو اتأخر يدفع العشا، وعشا النهارده عليه", "rationale": "«si llego tarde, pago la cena» ولونا ضافت «la de hoy también la pagas tú»."}, {"q": "إيه اللي خلّى الموقف ينتهي بضحك؟", "options": ["لونا قدمت الشكوى بكشف مضحك، وباكو اعترف من غير ما حد يهينه", "لونا سكتت خالص وما ردتش عليه", "باكو اعتذر من أول ما وصل من غير نقاش"], "answer": "لونا قدمت الشكوى بكشف مضحك، وباكو اعترف من غير ما حد يهينه", "rationale": "باكو ضحك وقال «Está bien, me has ganado» بعد ما عرف إنها بتحسب تأخيره من سنين."}]}, {"id": "c1-subida-alquiler", "level": "C1", "title": "صاحب العقار عايز يزود الإيجار", "desc": "باكو صاحب الشقة عايز يزود الإيجار ولونا ساكنة قديمة وعارفة السوق كويس. مفاوضة هادية ومشدودة.", "lines": [{"speaker": "paco", "es": "Luna, gracias por recibirme. Voy al grano: el contrato se renueva en dos meses y el precio de la zona ha subido mucho.", "ar": "يا لونا، شكرًا إنك استقبلتيني. هدخل في الموضوع على طول: العقد بيتجدد بعد شهرين وأسعار المنطقة زادت جدًا."}, {"speaker": "luna", "es": "¿Cuánto piensa subirme?", "ar": "حضرتك ناوي تزيدلي كام؟"}, {"speaker": "paco", "es": "Cincuenta euros al mes. Sigue siendo menos de lo que piden por pisos peores en esta calle.", "ar": "خمسين يورو في الشهر. وده لسه أقل من اللي بيطلبوه في شقق أوحش في نفس الشارع."}, {"speaker": "luna", "es": "Mire, Paco, yo también me he mirado los precios. Los pisos que usted dice llevan meses anunciados sin alquilarse. El precio que piden no es el precio que pagan.", "ar": "بص يا أستاذ باكو، أنا كمان باصة على الأسعار. الشقق اللي حضرتك بتتكلم عنها قاعدة شهور معلنة من غير ما تتأجر. السعر المطلوب مش هو السعر المدفوع."}, {"speaker": "paco", "es": "Puede ser, pero el mío se alquila mañana. Es una zona con mucha demanda.", "ar": "ممكن، بس شقتي هتتأجر بكرة. دي منطقة عليها طلب كبير."}, {"speaker": "luna", "es": "Se alquila mañana, sí. Y luego usted tiene un inquilino nuevo que no conoce, que a saber si le paga a tiempo o le destroza la cocina. Yo llevo cuatro años pagando el día uno, y la caldera nueva se la pagué a medias, ¿se acuerda?", "ar": "هتتأجر بكرة، أيوه. وبعدها هيبقى عند حضرتك مستأجر جديد متعرفوش، مين يدري هيدفع في معاده ولا هيبوظ المطبخ. أنا من أربع سنين بدفع أول كل شهر، والسخان الجديد دفعت نصه مع حضرتك، فاكر؟"}, {"speaker": "paco", "es": "Y se lo agradezco, de verdad. Pero usted entenderá que yo tampoco puedo regalar el dinero.", "ar": "وأنا مقدّر ده بجد. بس أكيد فاهمة إني أنا كمان مش أقدر أدي فلوس ببلاش."}, {"speaker": "luna", "es": "No le pido que regale nada. Le pido que valore lo que tiene: un inquilino que no le da problemas y que cuida el piso como si fuera suyo. ¿Cuánto le cuesta un mes de piso vacío entre inquilino e inquilino? ¿Seiscientos euros? ¿Más?", "ar": "مش بطلب من حضرتك تدي حاجة ببلاش. بطلب من حضرتك تقدّر اللي عندك: مستأجرة مش بتعمل مشاكل وبتحافظ على الشقة كأنها بتاعتها. شهر الشقة فاضية بين مستأجر والتاني بيكلف كام؟ ستمية يورو؟ أكتر؟"}, {"speaker": "paco", "es": "Ya veo que se lo ha pensado, y bien pensado.", "ar": "شايف إن حضرتك مجهزة حساباتك، ومجهزاها صح."}, {"speaker": "luna", "es": "Me lo he pensado porque me gusta esta casa y quiero quedarme. Por eso le propongo esto: veinticinco euros de subida ahora, y otros veinticinco dentro de un año si el mercado sigue subiendo. Usted cobra más, yo no me voy, y nadie busca pisos ni inquilinos.", "ar": "جهزت حساباتي عشان بحب البيت ده وعايزة أفضل فيه. عشان كده بعرض على حضرتك: خمسة وعشرين يورو زيادة دلوقتي، وخمسة وعشرين تانيين بعد سنة لو السوق فضل زايد. حضرتك هتقبض أكتر، أنا مش هسيب، ومحدش هيدور لا على شقة ولا على مستأجر."}, {"speaker": "paco", "es": "Treinta ahora y quince más dentro de un año.", "ar": "تلاتين دلوقتي وخمستاشر كمان بعد سنة."}, {"speaker": "luna", "es": "Trato hecho. Y me lo manda por escrito esta semana, que luego los números bailan.", "ar": "اتفقنا. وابعتهولي مكتوب الأسبوع ده، عشان الأرقام بتتلخبط بعدين."}], "questions": [{"q": "باكو افتتح المفاوضة بإيه؟", "options": ["طلب منها تخلي الشقة خلال شهرين بالكتير", "زيادة خمسين يورو لأن أسعار المنطقة زادت", "عرض تجديد العقد بنفس السعر القديم لسنة كمان"], "answer": "زيادة خمسين يورو لأن أسعار المنطقة زادت", "rationale": "قال «Voy al grano» يعني هقول المطلوب على طول، وبعدين «Cincuenta euros al mes»."}, {"q": "لونا ردّت على حجة السوق إزاي؟", "options": ["الشقق المعلنة بأسعار عالية قاعدة شهور من غير ما تتأجر", "قالتله إنها مش مهتمة بأسعار السوق خالص", "قالتله إن الأسعار نزلت السنة دي فعلًا"], "answer": "الشقق المعلنة بأسعار عالية قاعدة شهور من غير ما تتأجر", "rationale": "«llevan meses anunciados sin alquilarse. El precio que piden no es el precio que pagan» يعني سعر الإعلان مش سعر الصفقة."}, {"q": "ورقة لونا الأقوى في المفاوضة؟", "options": ["إنها محامية وعارفة كل قوانين الإيجار وهترفع قضية", "إن عندها معارف قوية في كل شركات العقارات الكبيرة في المدينة", "تاريخها كمستأجرة مثالية: بتدفع أول كل شهر وشاركت في السخان"], "answer": "تاريخها كمستأجرة مثالية: بتدفع أول كل شهر وشاركت في السخان", "rationale": "«llevo cuatro años pagando el día uno, y la caldera nueva se la pagué a medias» يعني بتدفع أول كل شهر وشاركت في السخان."}, {"q": "العرض اللي قدمته لونا؟", "options": ["رفض أي زيادة خالص مهما كان السبب", "زيادة خمسة وعشرين دلوقتي وخمسة وعشرين كمان بعد سنة لو السوق فضل زايد", "موافقة على الخمسين زي ما طلب بالظبط"], "answer": "زيادة خمسة وعشرين دلوقتي وخمسة وعشرين كمان بعد سنة لو السوق فضل زايد", "rationale": "«veinticinco euros de subida ahora, y otros veinticinco dentro de un año si el mercado sigue subiendo»."}, {"q": "الصفقة النهائية؟", "options": ["تلاتين دلوقتي وخمستاشر كمان بعد سنة", "خمسين زيادة كاملة من أول شهر", "خمسة وعشرين بس من غير زيادة تانية"], "answer": "تلاتين دلوقتي وخمستاشر كمان بعد سنة", "rationale": "باكو قال «Treinta ahora y quince más dentro de un año» ولونا قالت «Trato hecho»."}, {"q": "ليه لونا طلبت الاتفاق مكتوب؟", "options": ["عشان عايزة تنسحب من الاتفاق بعدين", "عشان محاميها طلب منها كده", "عشان الأرقام ما تتلخبطش بعدين"], "answer": "عشان الأرقام ما تتلخبطش بعدين", "rationale": "قالت «me lo manda por escrito esta semana, que luego los números bailan» يعني الأرقام بتتلخبط بعدين."}]}, {"id": "c2-ascenso-perdido", "level": "C2", "title": "الترقية اللي راحت لغيري", "desc": "لونا اتخطفت منها ترقية لزميل، وبتطلب مقابلة مع مديرها باكو تعرف الحقيقة من غير ما تحرق مراكبها.", "lines": [{"speaker": "luna", "es": "Gracias por verme, Paco. Iré directa: quiero entender qué le faltó a mi candidatura para la dirección del departamento.", "ar": "شكرًا إنك وافقت تقابلني يا باكو. هدخل في الموضوع: عايزة أفهم إيه اللي ناقص في ملفي لإدارة القسم."}, {"speaker": "paco", "es": "Y yo te agradezco que preguntes en vez de hacer conjeturas. Mira, tu candidatura era excelente. La de Andrés también.", "ar": "وأنا بشكرك إنك بتسألي بدل ما تفترضي. بصي، ملفك كان ممتاز. ملف أندريس كمان."}, {"speaker": "luna", "es": "Eso lo entiendo. Lo que no entiendo es qué tenía la suya que no tuviera la mía, porque los resultados de mi equipo hablan solos.", "ar": "ده أنا فاهماه. اللي مش فاهماه إيه اللي كان في ملفه ومش موجود في ملفي، لأن نتايج فريقي بتتكلم لوحدها."}, {"speaker": "paco", "es": "Y hablan, nadie lo discute. Pero el puesto no era solo de resultados. Andrés llevaba dos años en proyectos internacionales, y la dirección quiere abrir ese mercado.", "ar": "وبتتكلم فعلاً، محدش بيختلف على ده. بس الوظيفة مش بس نتايج. أندريس بقاله سنتين في مشاريع دولية، والإدارة ناوية تفتح السوق ده."}, {"speaker": "luna", "es": "O sea que el criterio decisivo era un perfil que, por mucho que rindiera, yo no podía tener, porque nunca se me ofreció uno de esos proyectos.", "ar": "يعني المعيار الحاسم كان بروفايل مهما اشتغلت كويس مستحيل يكون عندي، لأني عمري ما اتعرض عليّا مشروع من دول."}, {"speaker": "paco", "es": "Si te digo que no, te miento. Se le ofrecieron a él porque él los pidió. Ahí sí te digo algo: tú nunca pides nada. Rindes mejor que nadie y te quedas esperando a que lo noten.", "ar": "لو قلتلك لأ، هكون بكدب عليكي. اتعرضوا عليه عشان هو طلبهم. وهنا هقولك حاجة بجد: إنتي عمرك ما طلبتي حاجة. بتشتغلي أحسن من الكل وتستني حد يلاحظ."}, {"speaker": "luna", "es": "¿Me está diciendo que el error fue no llamar a su puerta?", "ar": "بتقول إن غلطتي إني ما خبطتش على باب حضرتك؟"}, {"speaker": "paco", "es": "Te estoy diciendo que en esta empresa hay dos formas de ascender: ser imprescindible, que tú lo eres, y que se te vea pidiendo el siguiente escalón, que es lo que hizo Andrés. La próxima plaza se abrirá en un año, como mucho. Lo que hagas hasta entonces cuenta.", "ar": "بقولك إن في الشركة دي طريقتين للترقية: إنك تبقي حاجة مفيش زيها، وإنتي كده فعلاً، وإن الناس تشوفك وإنتي بتطلبي الدرجة اللي بعدها، وده اللي أندريس عمله. الوظيفة الجاية هتتفتح خلال سنة كحد أقصى. اللي هتعمليه لحد ساعتها هو اللي هيتحسب."}, {"speaker": "luna", "es": "Entonces pido formalmente el proyecto internacional que se está gestando. Y pido que conste en algún sitio que lo he pedido.", "ar": "يبقى أنا هطلب رسميًا المشروع الدولي اللي بيتجهز. وبطلب إن طلبي يتسجل في محضر رسمي."}, {"speaker": "paco", "es": "Consta desde hoy. Y una cosa más, ya que estamos siendo directos: si en un año no se abre nada, ¿qué harás?", "ar": "اتسجل من النهارده. وحاجة كمان، ما دمنا بنتكلم بصراحة: لو سنة عدت ومفيش حاجة اتفتحت، هتعملي إيه؟"}, {"speaker": "luna", "es": "Le voy a ser tan directa como usted: tengo dos ofertas guardadas en el cajón desde hace meses. No las he respondido porque creo en este equipo. Pero creer tiene fecha de caducidad.", "ar": "هكون صريحة زي حضرتك بالظبط: عندي عرضين محفوظين في الدرج من شهور. مارديتش عليهم لأني مؤمنة بالفريق ده. بس ثقتي فيه ليها تاريخ صلاحية."}, {"speaker": "paco", "es": "Recibido. Y créeme, lo voy a tener muy en cuenta.", "ar": "وصلت الرسالة. وصدقيني، هاخد ده في الحسبان جدًا."}], "questions": [{"q": "ليه أندريس خد الترقية رغم إن نتايج لونا كانت قوية؟", "options": ["الوظيفة محتاجة خبرة دولية والإدارة ناوية تفتح سوق برة", "أندريس قريب المدير وده اللي حسم الموضوع في الآخر", "نتايج لونا فعلًا كانت أضعف من المطلوب في آخر سنتين تقريبًا"], "answer": "الوظيفة محتاجة خبرة دولية والإدارة ناوية تفتح سوق برة", "rationale": "قال «la dirección quiere abrir ese mercado» يعني الإدارة ناوية تفتح السوق ده. مفيش قرايب ولا نتايج ضعيفة في الكلام."}, {"q": "إيه المفارقة اللي كشفتها لونا؟", "options": ["إن أندريس أصغر منها في السن بكتير", "إن الترقية دي أصلاً من غير زيادة في المرتب", "المعيار الحاسم بروفايل مستحيل يكون عندها لأن المشاريع دي عمري ما اتعرضت عليها"], "answer": "المعيار الحاسم بروفايل مستحيل يكون عندها لأن المشاريع دي عمري ما اتعرضت عليها", "rationale": "قالت «un perfil que, por mucho que rindiera, yo no podía tener» وباكو اعترف: «Si te digo que no, te miento» يعني لو قال لأ يبقى بيكدب."}, {"q": "تشخيص باكو لمشكلة لونا؟", "options": ["إنها بتتكلم كتير في الاجتماعات من غير فايدة", "بتشتغل أحسن من الكل بس عمرها ما طلبت حاجة ومستنية حد يلاحظ", "إنها مش بتشتغل كويس أصلاً في الفترة الأخيرة"], "answer": "بتشتغل أحسن من الكل بس عمرها ما طلبت حاجة ومستنية حد يلاحظ", "rationale": "وصفها إنها «esperando a que lo noten» يعني مستنية حد يلاحظ."}, {"q": "إيه اللي لونا عملته فورًا بعد النصيحة؟", "options": ["طلبت رسميًا المشروع الدولي وإن طلبها يتسجل", "قدمت استقالتها على المكتب في نفس اليوم قبل ما تفكر", "راحت اشتكت أندريس للإدارة العليا في نفس اليوم"], "answer": "طلبت رسميًا المشروع الدولي وإن طلبها يتسجل", "rationale": "«pido formalmente el proyecto internacional» يعني طلبت المشروع رسمي، وطلبت إن طلبها يتسجل. استقالة أو شكوى ما حصلوش."}, {"q": "رسالة لونا المبطّنة الأخيرة كانت إيه؟", "options": ["إنها هتستقيل بكرة الصبح أول ما توصل الشغل ومن غير رجعة", "إنها مش مهتمة بالترقية دي أصلاً من زمان", "عندها عروض برة وهتصبر لحد معين، بس صبرها مش مفتوح"], "answer": "عندها عروض برة وهتصبر لحد معين، بس صبرها مش مفتوح", "rationale": "قالت إن عندها عرضين في الدرج و«creer tiene fecha de caducidad» يعني الثقة ليها تاريخ صلاحية، من غير كلمة تهديد واحدة."}, {"q": "إيه الطريقتين للترقية في الشركة حسب باكو؟", "options": ["تبقى قريب من المديرين وتسافر معاهم", "تبقى حاجة مفيش زيها، وتبان وإنت بتطلب الدرجة اللي بعدها", "تشتغل ساعات زيادة وتسكت عن حقك"], "answer": "تبقى حاجة مفيش زيها، وتبان وإنت بتطلب الدرجة اللي بعدها", "rationale": "قال «ser imprescindible» يعني مفيش زيك، و«que se te vea pidiendo el siguiente escalón» يعني تبين وإنت بتطلب الدرجة اللي بعدها."}]}, {"id": "c2-oferta-competencia", "level": "C2", "title": "عرض من المنافس", "desc": "باكو جاله عرض من شركة منافسة وبيقول لمديرته لونا، والاتنين بيلعبوا لعبة ولاء وطموح بكلمات محسوبة.", "lines": [{"speaker": "paco", "es": "Luna, ¿tienes diez minutos? Es algo que prefiero contarte yo antes de que llegue por otros cauces.", "ar": "يا لونا، عندك عشر دقايق؟ في حاجة أحب أقولهالك أنا قبل ما توصلك من حد تاني."}, {"speaker": "luna", "es": "Cuéntame.", "ar": "قول."}, {"speaker": "paco", "es": "Me han hecho una oferta. De la competencia. Buena, la verdad.", "ar": "جالي عرض. من المنافس بتاعنا. عرض كويس، بصراحة."}, {"speaker": "luna", "es": "Ya. ¿Y vienes a despedirte o a negociar? Porque una cosa la haces con Recursos Humanos y la otra, conmigo.", "ar": "أها. وإنت جاي تقول مع السلامة ولا تفاوضني؟ لأن واحدة منهم بتتعمل مع الموارد البشرية والتانية معايا أنا."}, {"speaker": "paco", "es": "Si quisiera irme, ya estaría escribiendo el correo. Vengo porque llevo seis años aquí y porque quiero saber si mi sitio sigue siendo aquí.", "ar": "لو كنت عايز أمشي، كنت خلاص بكتب الإيميل. أنا جاي عشان بقالي ست سنين هنا وعشان عايز أعرف لو كان مكاني لسه هنا ولا لأ."}, {"speaker": "luna", "es": "Eso es una respuesta bonita. También es la respuesta de quien quiere una contraoferta. No me ofende, ojo; me parece legítimo. Pero hablemos claro: ¿qué te falta aquí que allí te sobra?", "ar": "دي إجابة حلوة. ودي كمان إجابة واحد عايز عرض مضاد. ومش زعلانة منك، خد بالك؛ ده حقك. بس خلينا نتكلم بصراحة: إيه اللي ناقصك هنا وموجود عندهم هناك؟"}, {"speaker": "paco", "es": "Dos cosas. El sueldo, un treinta por ciento. Y liderar el equipo nuevo que están montando. Aquí hago el trabajo de líder sin el título ni el sueldo desde hace dos años.", "ar": "حاجتين. المرتب، تلاتين في المية. وقيادة الفريق الجديد اللي بيعملوه. بقالي سنتين بعمل شغل القائد هنا من غير اللقب ولا المرتب."}, {"speaker": "luna", "es": "Lo del título te lo debo, es verdad. Lo del sueldo, un treinta por ciento no puedo dártelo mañana. Puedo darte el título este mes y una revisión salarial seria en enero, con números por escrito.", "ar": "اللقب ده أنا متأخرة فيه، صح. المرتب، تلاتين في المية مش أقدر أديهالك بكرة. أقدر أديك اللقب الشهر ده ومراجعة مرتب جدية في يناير، بأرقام مكتوبة."}, {"speaker": "paco", "es": "¿Y quién me garantiza a mí que enero no vaya a ser como la última vez, cuando la revisión se quedó en agua de borrajas?", "ar": "وإيه اللي يضمنلي إن يناير مش هيبقى زي المرة اللي فاتت، لما المراجعة راحت في الهوى وفضلت مجرد كلام؟"}, {"speaker": "luna", "es": "Que esta vez te doy el título primero, que eso sí está en mi mano y no se desdice. Y que si en enero el número no te convence, yo misma te escribo la recomendación para donde quieras ir. Eso no te lo ofrece nadie.", "ar": "إني المرة دي هديك اللقب الأول، وده في إيدي فعلاً وماحدش يقدر يتراجع عنه. ولو الرقم في يناير معجبكش، أنا بنفسي هكتبلك خطاب توصية لأي مكان عايز تروحه. ده محدش هيعرضه عليك."}, {"speaker": "paco", "es": "¿Sabes que tu oferta es tan buena que casi me desarma?", "ar": "عارفة إن العرض بتاعك كويس لدرجة إنه خلاني مش عارف أرد تقريبًا؟"}, {"speaker": "luna", "es": "Es que no te quiero convencido, Paco. Te quiero con los ojos abiertos. Si te quedas, te quedas sabiendo lo que tienes. Y si te vas, que te vayas bien, que la vida da muchas vueltas y prefiero que nos veamos otra vez en buenos términos.", "ar": "عشان أنا مش عايزاك مقتنع، عايزاك فاتح عينيك. لو فضلت، تفضل وإنت عارف اللي معاك. ولو مشيت، تمشي على خير، لأن الدنيا صغيرة، وأنا عايزة نتقابل تاني وإحنا على خير."}, {"speaker": "paco", "es": "Vale. Dame el lunes para pensarlo. El título, mientras tanto, lo acepto desde ya.", "ar": "ماشي. اديني لحد يوم الاتنين أفكر. اللقب، لحد ما أفكر، موافق عليه من دلوقتي."}], "questions": [{"q": "ليه باكو قال للونا بنفسه عن العرض؟", "options": ["عشان يستقيل فورًا ويمشي في نفس اليوم", "عشان يفتخر قدامها بالعرض اللي جاله", "عشان توصل منه هو قبل ما توصل من حد تاني، ويفتح باب التفاوض"], "answer": "عشان توصل منه هو قبل ما توصل من حد تاني، ويفتح باب التفاوض", "rationale": "قال إنه فضّل يقولها بنفسه «antes de que llegue» يعني قبل ما توصلها من حد تاني، وإنه جاي يعرف لو مكانه لسه هنا."}, {"q": "لونا حددت الموقف بجملة واحدة، إيه هي؟", "options": ["«ممنوع تسيب الشركة مهما حصل، ماشي؟»", "«جاي تقولي مع السلامة ولا تفاوضني؟»", "«العرض بكام بالظبط؟ قولي الرقم دلوقتي»"], "answer": "«جاي تقولي مع السلامة ولا تفاوضني؟»", "rationale": "«¿vienes a despedirte o a negociar?» فرقت بين سيناريوهين: الوداع مكانه الموارد البشرية والتفاوض معاها."}, {"q": "باكو طالب بإيه بالظبط؟", "options": ["اللقب والمرتب، لأنه بقاله سنتين بيعمل شغل القائد من غيرهم", "مكتب أكبر وسواق خاص بالشركة", "إجازات أطول من اللي بياخدها دلوقتي"], "answer": "اللقب والمرتب، لأنه بقاله سنتين بيعمل شغل القائد من غيرهم", "rationale": "قال إنه بيعمل شغل القائد «sin el título ni el sueldo» يعني من غير اللقب ولا المرتب من سنتين."}, {"q": "ليه باكو شك في وعد يناير؟", "options": ["لأنه مش بيحب شهر يناير أصلاً وبيكره البرد", "لأن الشركة على وشك تفلس وتقفل أبوابها قريب", "لأن مراجعة المرة اللي فاتت فضلت مجرد كلام"], "answer": "لأن مراجعة المرة اللي فاتت فضلت مجرد كلام", "rationale": "قال إن المرة اللي فاتت المراجعة «se quedó en agua de borrajas» يعني راحت في الهوى وما حصلش منها حاجة."}, {"q": "الضمان اللي لونا قدمته؟", "options": ["حصة وأسهم كاملة في الشركة", "اللقب فورًا لأنه في إيدها، ولو رقم يناير معجبوش هتكتبله توصية بنفسها", "ضعف المرتب فورًا من أول الشهر الجاي"], "answer": "اللقب فورًا لأنه في إيدها، ولو رقم يناير معجبوش هتكتبله توصية بنفسها", "rationale": "قالت «te doy el título» الأول، وإنها بنفسها «te escribo la recomendación» لو رقم يناير معجبوش. مفيش أسهم ولا ضعف مرتب."}, {"q": "جملة لونا «no te quiero convencido... te quiero con los ojos abiertos» معناها إيه؟", "options": ["مش عايزاه يفضل غصب عنه؛ عايزاه فاتح عينيه", "إنها مش مهتمة بيه هو شخصيًا خالص ولا بمستقبله", "إنها عايزاه يمشي في أقرب وقت ممكن"], "answer": "مش عايزاه يفضل غصب عنه؛ عايزاه فاتح عينيه", "rationale": "كمّلت «te quedas sabiendo lo que tienes» يعني هتفضل وإنت عارف اللي معاك، ولو مشيت تمشي على خير."}]}, {"id": "c2-cena-familiar", "level": "C2", "title": "الخبر على العشا", "desc": "في عشا عائلي، باكو بيعلن إنه ولونا هيسافروا يعيشوا برة إسبانيا، وردود فعل أهلهم بتقول أكتر من كلامهم.", "lines": [{"speaker": "paco", "es": "Bueno, ya que estáis todos, mamá, papá... tenemos algo que contaros. Nos vamos a vivir fuera. A Chile.", "ar": "طيب، ما دمنا كلنا موجودين، يا ماما يا بابا... عندنا خبر نقوله. إحنا مسافرين نعيش برة. في تشيلي."}, {"speaker": "luna", "es": "Me ha salido un puesto allí. Es una oportunidad que no se da dos veces.", "ar": "جالي منصب هناك. فرصة مش بتتكرر مرتين."}, {"speaker": "paco", "es": "Mamá, di algo.", "ar": "يا ماما، ردي بقى."}, {"speaker": "luna", "es": "Es normal que necesiten un momento.", "ar": "طبيعي يحتاجوا لحظة."}, {"speaker": "paco", "es": "Un momento sí. Silencio total, no.", "ar": "لحظة أيوه. صمت كامل، لأ."}, {"speaker": "luna", "es": "Paco, tranquilo.", "ar": "يا باكو اهدى."}, {"speaker": "paco", "es": "Es que ya sé lo que viene: que si estamos locos, que si los nietos, que si aquí tienes todo. Llevamos meses pensándolo, no es un capricho.", "ar": "عشان أنا عارف اللي جاي: إننا مجانين، والأحفاد، وإن عندك هنا كل حاجة. إحنا بنفكر في ده من شهور، مش نزوة."}, {"speaker": "luna", "es": "Y aun así, es su derecho llevarse una sorpresa. Nosotros tuvimos meses; ellos han tenido diez segundos.", "ar": "وحتى كده، من حقهم يتفاجئوا. إحنا كان عندنا شهور؛ هما عندهم عشر ثواني."}, {"speaker": "paco", "es": "Tienes razón. Perdón. Es que... yo también estoy asustado, ¿sabes? Y cuando me asusto me pongo a la defensiva.", "ar": "معاكي حق. آسف. عشان... أنا كمان خايف، عارفة؟ ولما بخاف بدخل في وضع الدفاع."}, {"speaker": "luna", "es": "Pues diles eso. Diles que estás asustado y que aun así lo vas a hacer. Eso lo entiende cualquier madre mejor que un discurso.", "ar": "طيب قولهم كده. قولهم إنك خايف وبرضه هتعملها. ده أي أم تفهمه أحسن من أي خطاب."}, {"speaker": "paco", "es": "Mamá... estoy asustado. Y aun así quiero ir. Y necesito que no me lo pongas más difícil, porque me cuesta lo mío ya.", "ar": "يا ماما... أنا خايف. وبرضه عايز أروح. ومحتاجك ماتصعبهاش عليّا أكتر، لأن الموضوع صعب عليّا أصلاً."}, {"speaker": "luna", "es": "Y yo os prometo que, por muy lejos que esté Chile (que no está en la luna, aunque lo parezca), habrá vuelos y videollamadas.", "ar": "وأنا بوعدكم إنه مهما كانت تشيلي بعيدة، وهي مش على القمر ولو باينة كده، هيبقى فيه طيران وفيديو كولات."}, {"speaker": "paco", "es": "Bueno, mamá, ahora sí: ¿qué dices?", "ar": "طيب يا ماما، دلوقتي بقى: هتقولي إيه؟"}], "questions": [{"q": "الخبر اللي اتعلن على العشا؟", "options": ["باكو اتفصل من شغله فجأة الأسبوع اللي فات ومن غير تعويض", "باكو ولونا مسافرين يعيشوا في تشيلي بسبب منصب لونا", "لونا حامل في شهورها الأولى والعيلة هتكبر"], "answer": "باكو ولونا مسافرين يعيشوا في تشيلي بسبب منصب لونا", "rationale": "«Nos vamos a vivir fuera. A Chile» و«Me ha salido un puesto allí» يعني جالها منصب هناك. حمل أو فصل ما اتذكروش."}, {"q": "رد فعل أم باكو الأول؟", "options": ["صمت تام", "فرحت وعيطت من الفرحة فورًا", "اتخانقت مع باكو على السفر"], "answer": "صمت تام", "rationale": "باكو قال إن اللي ضايقه هو «Silencio total» يعني سكوتها التام، وعشان كده قالها «di algo»."}, {"q": "ليه باكو اتنرفز من الصمت؟", "options": ["عشان أمه دايمًا بتتأخر في الرد عليه في كل حاجة", "عشان الأكل بيبرد على الترابيزة وهما ساكتين", "عشان هو كمان خايف، والخوف بيخليه يهاجم"], "answer": "عشان هو كمان خايف، والخوف بيخليه يهاجم", "rationale": "اعترف إنه لما بيخاف «me pongo a la defensiva» يعني بدخل في وضع الدفاع والهجوم."}, {"q": "لونا دافعت عن الأهل بجملة منصفة، إيه هي؟", "options": ["«خلينا نمشي من هنا فورًا»", "«إحنا كان عندنا شهور؛ هما عندهم عشر ثواني»", "«أهلك عمرهم ما بيحبوك أصلاً»"], "answer": "«إحنا كان عندنا شهور؛ هما عندهم عشر ثواني»", "rationale": "قالت إن هما كان عندهم «meses» يعني شهور يستوعبوا، والأهل عندهم «diez segundos» يعني عشر ثواني بس."}, {"q": "نصيحة لونا لباكو كانت إيه؟", "options": ["يقول لأمه إنه خايف وهيعملها برضه، لأن الصدق بيوصل أحسن من الخطب", "يكدب ويقول إنه مش خايف خالص", "يأجل السفر لحد ما أمه توافق"], "answer": "يقول لأمه إنه خايف وهيعملها برضه، لأن الصدق بيوصل أحسن من الخطب", "rationale": "قالت إن الكلام ده «lo entiende cualquier madre» يعني أي أم هتفهمه، أحسن من خطاب مظبوط."}, {"q": "القصة بتنتهي إزاي؟", "options": ["الأم وافقت فورًا وباركت السفر", "العيلة اتخانقت وكل واحد مشي في حاله", "الأم لسه ما ردتش، وباكو بقى مستعد يسمعها"], "answer": "الأم لسه ما ردتش، وباكو بقى مستعد يسمعها", "rationale": "القصة بتخلص بسؤال باكو «¿qué dices?» يعني بتقولي إيه، من غير ما نسمع رد أمه."}]}, {"id": "c2-disculpas-anos", "level": "C2", "title": "اعتذار اتأخر سنين", "desc": "بعد سنين قطيعة، باكو بيكلم لونا يعتذر عن حاجة قديمة. اللي مش بيتقال أهم من اللي بيتقال.", "lines": [{"speaker": "paco", "es": "Gracias por aceptar verme. No sabía si vendrías.", "ar": "شكرًا إنك وافقتي تقابليني. ما كنتش عارف إنتي هتيجي ولا لأ."}, {"speaker": "luna", "es": "Yo tampoco sabía si vendría. Y aquí estoy.", "ar": "وأنا كمان ما كنتش عارفة هاجي ولا لأ. وأنا أهو جيت."}, {"speaker": "paco", "es": "Te debo una conversación desde hace seis años. Lo de aquella noche, lo que dije delante de todos...", "ar": "مديونلك بكلام من ست سنين. موضوع الليلة دي، اللي قلته قدام الناس كلها..."}, {"speaker": "luna", "es": "No hace falta que lo repitas. Me acuerdo palabra por palabra. Ese es el problema de las palabras así: quien las dice las olvida; quien las oye las archiva.", "ar": "مش محتاج تعيده. أنا فاكراه كلمة كلمة. دي مشكلة الكلام من النوع ده: اللي بيقوله بينساه، واللي بيسمعه بيخزنه."}, {"speaker": "paco", "es": "No las he olvidado. Las he llevado todos estos años. Que es distinto.", "ar": "أنا مانسيتهوش. أنا شايله طول السنين دي. ودي حاجة تانية."}, {"speaker": "luna", "es": "¿Y a qué debo el honor, después de seis años?", "ar": "وإيه سبب الشرف ده بعد ست سنين؟"}, {"speaker": "paco", "es": "A que estuve a punto de escribirte veinte veces y las veinte borré el mensaje. Y a que el mes pasado me enteré de lo de tu padre, y pensé: si mañana te pasara algo, me quedaría con esto dentro para siempre.", "ar": "لأني كنت هكتبلك عشرين مرة، وكل مرة مسحت الرسالة. ولأني الشهر اللي فات عرفت موضوع والدك، وفكرت: لو بكرة حصلك حاجة، هفضل شايل ده جوايا للأبد."}, {"speaker": "luna", "es": "Así que vienes por ti. Para quitarte el peso.", "ar": "يعني إنت جاي عشان نفسك. عشان تشيل الحِمل ده عن صدرك."}, {"speaker": "paco", "es": "Vengo por mí, sí. Quien te dice que se disculpa solo por el otro, miente. Pero vengo también por ti, aunque no tengas por qué creértelo hoy.", "ar": "جاي عشان نفسي، أيوه. اللي بيقولك إنه بيعتذر عشان التاني بس، بيكدب. بس جاي كمان عشانك إنتي، ولو مش لازم تصدقي ده النهارده."}, {"speaker": "luna", "es": "Esa es la primera cosa honesta que me has dicho en años.", "ar": "دي أول حاجة صادقة قلتهالي من سنين."}, {"speaker": "paco", "es": "No te pido que lo dejes atrás, que sería pedir demasiado. Ni que volvamos a ser lo que éramos. Te pido diez minutos de vez en cuando. Un café como este. Sin promesas.", "ar": "مش بطلب منك تنسي، ده هيبقى طلب كبير. ولا نرجع زي زمان. بطلب عشر دقايق من وقت للتاني. قهوة زي دي. من غير وعود."}, {"speaker": "luna", "es": "¿Sabes qué es lo curioso? Que si me hubieras pedido perdón hace seis años, no te lo habría dado. Estaba demasiado enfadada para perdonar y demasiado orgullosa para admitir que te echaba de menos.", "ar": "عارف إيه الغريب؟ إنك لو طلبتلي السماح من ست سنين، ما كنتش هاديهولك. كنت زعلانة أوي عشان أسامح ومكابرة أوي عشان أعترف إنك وحشتني."}, {"speaker": "paco", "es": "¿Y ahora?", "ar": "ودلوقتي؟"}, {"speaker": "luna", "es": "Ahora estoy cansada de llevarlo. Que no es lo mismo que perdonarte, ojo. Pero es un sitio donde se puede empezar.", "ar": "دلوقتي أنا زهقت من شيله. وده مش نفس معنى إني سامحتك، خد بالك. بس ده مكان ممكن نبدأ منه."}, {"speaker": "paco", "es": "Me basta. De verdad, me basta.", "ar": "يكفيني. بجد، يكفيني."}], "questions": [{"q": "جملة لونا عن الكلام الجارح معناها إيه؟", "options": ["اللي بيقولها بينساها واللي بيسمعها بيخزنها", "الكلام مش مهم وبيتنسي بسرعة مهما كان جارح أو مؤلم", "هي نسيت الموضوع من زمان خالص"], "answer": "اللي بيقولها بينساها واللي بيسمعها بيخزنها", "rationale": "«quien las dice las olvida» يعني اللي بيقول بينسى، وباكو أكد إنه حامل الكلام كل السنين دي."}, {"q": "إيه اللي حرّك باكو دلوقتي بالذات؟", "options": ["شافها بالصدفة في الشارع الأسبوع اللي فات وقرر يروح يعتذر ليها", "صاحب مشترك بينهم نصحه إنه يروح يعتذر ليها", "عرف موضوع والد لونا وخاف يفضل شايل الندم للأبد"], "answer": "عرف موضوع والد لونا وخاف يفضل شايل الندم للأبد", "rationale": "قال إنه عرف «lo de tu padre» يعني موضوع والدها، وفكر: لو «te pasara algo» يعني حصلك حاجة، هيفضل شايل الندم للأبد."}, {"q": "لونا قالتله إنه جاي عشان نفسه. رده كان إيه؟", "options": ["زعل من الاتهام وقام مشي من القهوة على طول", "اعترف إنه جاي عشان نفسه، بس جاي عشانها كمان", "أنكر تمامًا وقال إنه جاي عشانها هي بس ومش عشانه خالص"], "answer": "اعترف إنه جاي عشان نفسه، بس جاي عشانها كمان", "rationale": "«Vengo por mí, sí» يعني جاي عشاني، أيوه، وقال إن اللي بيدّعي غير كده «miente» يعني بيكدب. ولونا اعتبرت ده أول صدق من سنين."}, {"q": "ليه لونا ما كانتش هتسامحه من ست سنين؟", "options": ["كانت زعلانة أوي عشان تسامح ومكابرة أوي عشان تعترف إنه وحشها", "كانت نسيت الموضوع خالص من زمان", "كانت مسافرة برة البلد طول المدة"], "answer": "كانت زعلانة أوي عشان تسامح ومكابرة أوي عشان تعترف إنه وحشها", "rationale": "قالت إنها كانت زعلانة أوي عشان تسامح ومكابرة أوي عشان تعترف إنها «te echaba de menos» يعني كنت وحشها."}, {"q": "لونا قالت «estoy cansada de llevarlo». معناها بالظبط إيه؟", "options": ["سامحته نهائيًا وكل حاجة رجعت زي زمان", "قررت إنها مش هتشوفه تاني أبد", "زهقت من شيل الزعل، وده بداية مش مسامحة كاملة"], "answer": "زهقت من شيل الزعل، وده بداية مش مسامحة كاملة", "rationale": "نبّهت إن ده «no es lo mismo que perdonarte» يعني مش نفسه المسامحة، بس مكان ممكن نبدأ منه."}, {"q": "إيه اللي طلبه باكو في الآخر؟", "options": ["تنسى خالص اللي حصل من ست سنين وكأنه ما حصلش", "عشر دقايق من وقت للتاني، قهوة زي دي، من غير وعود", "يرجعوا أصحاب مقربين زي زمان ابتداءً من النهارده"], "answer": "عشر دقايق من وقت للتاني، قهوة زي دي، من غير وعود", "rationale": "«Te pido diez minutos de vez en cuando» يعني عشر دقايق من وقت للتاني، وقال صراحة إنه مش طالب رجوع زي زمان."}]},{"id": "b1-cancelar-gimnasio", "level": "B1", "title": "إلغاء الاشتراك في النادي", "desc": "تريد لونا إلغاء اشتراكها في النادي الرياضي، فيعرض عليها الموظف بدائل.", "lines": [{"speaker": "luna", "es": "Buenos días, quiero cancelar mi suscripción al gimnasio.", "ar": "صباح الخير، أريد إلغاء اشتراكي في النادي الرياضي."}, {"speaker": "paco", "es": "Claro. ¿Puedo preguntarle el motivo?", "ar": "بالتأكيد. هل يمكنني أن أسألكِ عن السبب؟"}, {"speaker": "luna", "es": "Casi no tengo tiempo y hace meses que no vengo.", "ar": "لا أملك وقتًا تقريبًا، ومنذ أشهر لم آتِ."}, {"speaker": "paco", "es": "Lo entiendo. Podemos congelar la cuota durante unos meses si lo prefiere.", "ar": "أفهم ذلك. يمكننا تجميد الاشتراك لبضعة أشهر إن أحببتِ."}, {"speaker": "luna", "es": "¿Y cuánto costaría congelarla?", "ar": "وكم سيكلّف التجميد؟"}, {"speaker": "paco", "es": "Solo una pequeña parte de lo que paga ahora.", "ar": "جزءًا صغيرًا فقط ممّا تدفعينه الآن."}, {"speaker": "luna", "es": "Aun así, prefiero cancelar. ¿Tengo que pagar alguna penalización?", "ar": "ومع ذلك أفضّل الإلغاء. هل عليّ دفع غرامة؟"}, {"speaker": "paco", "es": "No, si avisa con tiempo. Y usted lo hace hoy, así que la baja será efectiva el mes que viene.", "ar": "لا، إذا أبلغتِ مبكرًا. وأنتِ تفعلين ذلك اليوم، لذا سيصبح الإلغاء ساريًا في الشهر القادم."}, {"speaker": "luna", "es": "Perfecto. ¿Necesito firmar algo?", "ar": "ممتاز. هل أحتاج إلى توقيع شيء؟"}, {"speaker": "paco", "es": "Sí, este formulario. Y tiene que devolver la tarjeta de acceso.", "ar": "نعم، هذا النموذج. وعليكِ إعادة بطاقة الدخول."}, {"speaker": "luna", "es": "Aquí la tiene. Muchas gracias por su ayuda.", "ar": "تفضّل، ها هي. شكرًا جزيلًا على مساعدتك."}, {"speaker": "paco", "es": "A usted. Si cambia de opinión, será bienvenida.", "ar": "بل شكرًا لكِ. وإذا غيّرتِ رأيكِ فأهلًا بكِ."}], "questions": [{"q": "لماذا تريد لونا إلغاء الاشتراك؟", "options": ["السعر مرتفع جدًا", "لا تملك وقتًا ولم تحضر منذ أشهر", "ستنتقل إلى مدينة أخرى"], "answer": "لا تملك وقتًا ولم تحضر منذ أشهر", "rationale": "قالت «Casi no tengo tiempo y hace meses que no vengo»، أي أنها لا تملك وقتًا ولم تحضر منذ أشهر. لم تذكر السعر ولا الانتقال."}, {"q": "ما الذي اقترحه الموظف أولًا؟", "options": ["تجميد الاشتراك لبضعة أشهر", "تخفيض السعر إلى النصف", "الانتقال إلى فرع آخر"], "answer": "تجميد الاشتراك لبضعة أشهر", "rationale": "قال «Podemos congelar la cuota durante unos meses»، أي يمكن تجميد الاشتراك لبضعة أشهر."}, {"q": "هل ستدفع لونا غرامة؟", "options": ["نعم، غرامة ثابتة", "لا، لأنها أبلغت مبكرًا", "نعم، نصف قيمة الاشتراك"], "answer": "لا، لأنها أبلغت مبكرًا", "rationale": "قال الموظف «No, si avisa con tiempo»، فلا غرامة لمن يبلّغ مبكرًا، ولونا تفعل ذلك اليوم."}, {"q": "ماذا عليها أن تفعل قبل الانصراف؟", "options": ["دفع المبلغ المتبقي", "إحضار صورة من الهوية", "توقيع نموذج وإعادة بطاقة الدخول"], "answer": "توقيع نموذج وإعادة بطاقة الدخول", "rationale": "قال «este formulario. Y tiene que devolver la tarjeta de acceso»، أي توقيع النموذج وإعادة بطاقة الدخول."}]},{"id": "b2-sala-reuniones", "level": "B2", "title": "قاعة الاجتماعات المحجوزة مرتين", "desc": "تجد لونا فريقًا آخر داخل القاعة التي حجزتها، فيحاول الموظف حلّ المشكلة.", "lines": [{"speaker": "luna", "es": "Buenos días. Tenía reservada la sala de reuniones, pero hay otro equipo dentro.", "ar": "صباح الخير. كنت قد حجزت قاعة الاجتماعات، لكن هناك فريقًا آخر بداخلها."}, {"speaker": "paco", "es": "Vaya, lo siento. Déjeme comprobar el sistema.", "ar": "آسف جدًا. اسمحي لي أن أتحقق من النظام."}, {"speaker": "paco", "es": "Efectivamente, hay un error: la reserva aparece duplicada.", "ar": "فعلًا، هناك خطأ: الحجز يظهر مكرّرًا."}, {"speaker": "luna", "es": "Es la tercera vez este mes. Mi equipo lleva media hora esperando.", "ar": "هذه ثالث مرة هذا الشهر. وفريقي ينتظر منذ نصف ساعة."}, {"speaker": "paco", "es": "Entiendo su enfado. Puedo ofrecerle la sala pequeña de la planta baja ahora mismo.", "ar": "أتفهّم غضبكِ. يمكنني أن أعرض عليكِ القاعة الصغيرة في الطابق الأرضي حالًا."}, {"speaker": "luna", "es": "Es demasiado pequeña. Somos un equipo grande y necesitamos el proyector.", "ar": "إنها صغيرة جدًا. فريقنا كبير ونحتاج إلى جهاز العرض."}, {"speaker": "paco", "es": "En ese caso, la sala grande quedará libre dentro de un cuarto de hora.", "ar": "في هذه الحالة، ستصبح القاعة الكبيرة متاحة بعد ربع ساعة."}, {"speaker": "luna", "es": "Está bien, esperaremos. Pero quiero que quede constancia de la queja por escrito.", "ar": "حسنًا، سننتظر. لكنني أريد أن تُسجَّل الشكوى كتابةً."}, {"speaker": "paco", "es": "Por supuesto. Le enviaré un correo para que lo confirme, y avisaré al responsable del sistema.", "ar": "بالتأكيد. سأرسل إليكِ رسالة بريد لتؤكّديها، وسأُبلغ المسؤول عن النظام."}, {"speaker": "luna", "es": "Se lo agradezco. Y que no vuelva a ocurrir.", "ar": "أشكرك. وأرجو ألّا يتكرّر ذلك."}, {"speaker": "paco", "es": "Haré todo lo posible para que no se repita.", "ar": "سأبذل ما في وسعي حتى لا يتكرّر."}], "questions": [{"q": "ما سبب المشكلة؟", "options": ["القاعة مغلقة للصيانة", "الحجز مكرّر فدخل فريق آخر القاعة", "لونا وصلت في الموعد الخطأ"], "answer": "الحجز مكرّر فدخل فريق آخر القاعة", "rationale": "قال الموظف «la reserva aparece duplicada»، أي أن الحجز مكرّر، ولذلك كان فريق آخر داخل القاعة."}, {"q": "لماذا ترفض لونا القاعة الصغيرة؟", "options": ["لأنها بعيدة", "لأنها لا تتّسع لفريق كبير ولا يوجد فيها جهاز عرض", "لأنها محجوزة أيضًا"], "answer": "لأنها لا تتّسع لفريق كبير ولا يوجد فيها جهاز عرض", "rationale": "قالت «Es demasiado pequeña. Somos un equipo grande y necesitamos el proyector»."}, {"q": "ماذا تقرّر لونا في النهاية؟", "options": ["إلغاء الاجتماع", "الانتظار حتى تصبح القاعة الكبيرة متاحة", "إجراء الاجتماع في الممر"], "answer": "الانتظار حتى تصبح القاعة الكبيرة متاحة", "rationale": "قالت «Está bien, esperaremos»، فهي ستنتظر ربع ساعة حتى تُخلى القاعة الكبيرة."}, {"q": "ماذا تطلب لونا بخصوص الشكوى؟", "options": ["أن تُسجَّل كتابةً", "أن تُحذف من النظام", "أن تُرسل إلى فريقها"], "answer": "أن تُسجَّل كتابةً", "rationale": "قالت «quiero que quede constancia de la queja por escrito»، أي أن تُسجَّل الشكوى كتابةً."}]},{"id": "c1-teletrabajo-propuesta", "level": "C1", "title": "اقتراح العمل عن بُعد", "desc": "تعرض لونا على مديرها اقتراحًا لتغيير جدول عملها مدعومًا بتقرير عن أدائها.", "lines": [{"speaker": "luna", "es": "¿Tiene un momento? Quería plantearle una propuesta sobre mi horario.", "ar": "هل لديك لحظة؟ أردت أن أطرح عليك اقتراحًا بشأن جدول عملي."}, {"speaker": "paco", "es": "Claro, adelante. Cuénteme.", "ar": "بالطبع، تفضّلي. أخبريني."}, {"speaker": "luna", "es": "Desde que cambió el equipo, paso mucho tiempo en desplazamientos. Me gustaría teletrabajar algunos días por semana.", "ar": "منذ أن تغيّر الفريق وأنا أقضي وقتًا طويلًا في التنقّل. وأودّ العمل عن بُعد بضعة أيام في الأسبوع."}, {"speaker": "paco", "es": "Lo entiendo, pero la dirección se ha mostrado reticente a ampliar el teletrabajo.", "ar": "أتفهّم ذلك، لكن الإدارة كانت متردّدة في توسيع العمل عن بُعد."}, {"speaker": "luna", "es": "Lo sé. Por eso he preparado un informe con los resultados de los últimos meses, para demostrar que mi rendimiento no se ve afectado.", "ar": "أعرف ذلك. لهذا أعددت تقريرًا بنتائج الأشهر الأخيرة لأثبت أن أدائي لا يتأثر."}, {"speaker": "paco", "es": "Aprecio la iniciativa. ¿Y cómo garantizaría la coordinación con el resto del equipo?", "ar": "أقدّر هذه المبادرة. وكيف ستضمنين التنسيق مع بقية الفريق؟"}, {"speaker": "luna", "es": "Estaría disponible en las reuniones clave y mantendría abiertos los canales de comunicación durante toda la jornada.", "ar": "سأكون متاحة في الاجتماعات الأساسية، وسأُبقي قنوات التواصل مفتوحة طوال اليوم."}, {"speaker": "paco", "es": "No me opongo, pero necesito el visto bueno de recursos humanos.", "ar": "لا أعارض، لكنني أحتاج إلى موافقة قسم الموارد البشرية."}, {"speaker": "luna", "es": "¿Podría presentarles la propuesta junto conmigo? Así evitaríamos malentendidos.", "ar": "هل يمكنك تقديم الاقتراح معي؟ بهذا نتفادى سوء الفهم."}, {"speaker": "paco", "es": "De acuerdo. Propongo un periodo de prueba de unos meses y, si funciona, lo formalizamos.", "ar": "موافق. أقترح فترة تجريبية لبضعة أشهر، وإن نجحت فإننا نُقرّها رسميًا."}, {"speaker": "luna", "es": "Me parece razonable. Gracias por escucharme.", "ar": "يبدو ذلك معقولًا. شكرًا لإصغائك."}], "questions": [{"q": "ما الذي تطلبه لونا؟", "options": ["زيادة في الراتب", "العمل عن بُعد بضعة أيام في الأسبوع", "الانتقال إلى فريق آخر"], "answer": "العمل عن بُعد بضعة أيام في الأسبوع", "rationale": "قالت «Me gustaría teletrabajar algunos días por semana»، أي العمل عن بُعد بضعة أيام أسبوعيًا."}, {"q": "ما العقبة التي ذكرها المدير؟", "options": ["الإدارة متردّدة في توسيع العمل عن بُعد", "ميزانية الشركة محدودة", "لونا جديدة في الشركة"], "answer": "الإدارة متردّدة في توسيع العمل عن بُعد", "rationale": "قال «la dirección se ha mostrado reticente a ampliar el teletrabajo»، أي أن الإدارة متردّدة."}, {"q": "كيف تدعم لونا طلبها؟", "options": ["بتقرير عن نتائج الأشهر الأخيرة", "بطلب من زملائها", "بشهادة طبية"], "answer": "بتقرير عن نتائج الأشهر الأخيرة", "rationale": "قالت «he preparado un informe con los resultados de los últimos meses»."}, {"q": "ما الحلّ الذي يقترحه المدير في النهاية؟", "options": ["رفض الطلب نهائيًا", "فترة تجريبية لبضعة أشهر ثم إقرارها إن نجحت", "تأجيل القرار إلى العام القادم"], "answer": "فترة تجريبية لبضعة أشهر ثم إقرارها إن نجحت", "rationale": "قال «Propongo un periodo de prueba de unos meses y, si funciona, lo formalizamos»."}]},{"id": "c2-premio-literario", "level": "C2", "title": "الجائزة الأدبية", "desc": "تتحدّث لونا إلى صحفي عن فوزها بجائزة أدبية وعن قلقها من الشهرة.", "lines": [{"speaker": "paco", "es": "Enhorabuena por el premio. Imagino que no se lo esperaba.", "ar": "مبروك على الجائزة. أظنّكِ لم تتوقّعيها."}, {"speaker": "luna", "es": "Para nada. Llevaba años escribiendo en la sombra, y de repente todo el mundo quiere entrevistarme.", "ar": "أبدًا. قضيت سنوات أكتب في الظلّ، وفجأة يريد الجميع محاورتي."}, {"speaker": "paco", "es": "¿Le abruma tanta atención?", "ar": "هل يُثقل عليكِ هذا القدر من الاهتمام؟"}, {"speaker": "luna", "es": "Un poco. Agradezco el reconocimiento, pero me inquieta que se hable más de mí que de la novela.", "ar": "قليلًا. أقدّر هذا التكريم، لكنّه يقلقني أن يُتحدَّث عنّي أكثر ممّا يُتحدَّث عن الرواية."}, {"speaker": "paco", "es": "Es el precio de la notoriedad, supongo. ¿Cree que el premio cambiará su manera de escribir?", "ar": "هذا ثمن الشهرة على ما أظن. هل تعتقدين أن الجائزة ستغيّر طريقتكِ في الكتابة؟"}, {"speaker": "luna", "es": "Ojalá que no. Temo caer en la tentación de escribir pensando en complacer al jurado.", "ar": "أرجو ألّا تفعل. أخشى أن أنجرف إلى الكتابة بهدف إرضاء لجنة التحكيم."}, {"speaker": "paco", "es": "Algunos críticos sostienen que la novela es deliberadamente ambigua. ¿Está de acuerdo?", "ar": "يرى بعض النقّاد أن الرواية غامضة عن قصد. هل توافقين؟"}, {"speaker": "luna", "es": "Más bien la considero honesta: la vida rara vez ofrece finales cerrados, y no veía por qué la ficción debía hacerlo.", "ar": "بل أراها صادقة: فالحياة نادرًا ما تقدّم نهايات مغلقة، ولم أجد سببًا لأن يفعل الخيال ذلك."}, {"speaker": "paco", "es": "Una postura valiente, sobre todo en un mercado que premia lo previsible.", "ar": "موقف شجاع، خاصة في سوق يكافئ ما يمكن توقّعه."}, {"speaker": "luna", "es": "Quizá, aunque confío en que los lectores agradezcan que no se les subestime.", "ar": "ربما، لكنني أثق بأن القرّاء يقدّرون ألّا يُستهان بهم."}], "questions": [{"q": "كيف استقبلت لونا خبر الفوز؟", "options": ["توقّعته منذ زمن", "فوجئت به تمامًا", "لم تهتم به"], "answer": "فوجئت به تمامًا", "rationale": "قالت «Para nada» ردًّا على أنها لم تتوقّعه، وأضافت أنها كانت تكتب في الظلّ منذ سنوات."}, {"q": "ما الذي يقلقها في الاهتمام الإعلامي؟", "options": ["أن يُتحدَّث عنها أكثر من الرواية", "أن تنخفض مبيعات الكتاب", "أن يعرف الناس عنوانها"], "answer": "أن يُتحدَّث عنها أكثر من الرواية", "rationale": "قالت «me inquieta que se hable más de mí que de la novela»."}, {"q": "ما الذي تخشاه بشأن كتابتها المقبلة؟", "options": ["أن تنقطع عن الكتابة", "أن تكتب لإرضاء لجنة التحكيم", "أن تتأثر بآراء الأصدقاء"], "answer": "أن تكتب لإرضاء لجنة التحكيم", "rationale": "قالت «Temo caer en la tentación de escribir pensando en complacer al jurado»."}, {"q": "كيف تصف الرواية؟", "options": ["غامضة عن قصد لإرباك القارئ", "صادقة لأن الحياة قلّما تقدّم نهايات مغلقة", "سهلة وسريعة القراءة"], "answer": "صادقة لأن الحياة قلّما تقدّم نهايات مغلقة", "rationale": "قالت «la considero honesta: la vida rara vez ofrece finales cerrados»."}]}].map(s=>({...s,questions:s.questions.map(q=>({...q,answer:q.options.indexOf(q.answer)}))})));
